function sbErr(j,st){
  var m=String(j&&(j.error_description||j.msg||j.message||j.error)||'').toLowerCase();
  if(m.indexOf('invalid login')>-1)return __("ایمیل یا رمز اشتباه است","Wrong e-mail or password");
  if(m.indexOf('already')>-1)return __("با این ایمیل قبلاً حساب ساخته شده؛ وارد شو","An account with this e-mail already exists; sign in");
  if(m.indexOf('password')>-1&&m.indexOf('6')>-1)return __("رمز دست‌کم ۶ نویسه باشد","The password needs at least 6 characters");
  if(m.indexOf('confirm')>-1)return __("اول ایمیلت را تأیید کن (پیام تأیید برایت فرستاده شد)","Confirm your e-mail first (a message was sent to you)");
  if(m.indexOf('rate')>-1||st===429)return __("درخواست‌ها زیاد بود؛ چند دقیقه بعد دوباره امتحان کن","Too many tries; wait a few minutes");
  if(m.indexOf('email')>-1&&m.indexOf('valid')>-1)return __("ایمیل درست نیست","That e-mail does not look right");
  return __("انجام نشد. دوباره امتحان کن","That did not work. Try again");
}
async function sbRefresh(s){
  if(sbRefP)return sbRefP;
  sbRefP=(async function(){
    try{
      await cwAdopt();var c2=sbSess();if(c2&&c2.exp>Date.now()/1000+60)return c2;s=c2||s;
      var r=await fetch(SB.url+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:SB.key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:s.rt})});
      if(r.status===400||r.status===401||r.status===403){sbKeep(null);return null}   /* the sign-in really ended */
      if(!r.ok)return s;
      var n=sbToSess(await r.json());if(n){sbKeep(n);return n}return s;
    }catch(e){return s}                                                              /* offline: keep what we have */
    finally{sbRefP=null}
  })();
  return sbRefP;
}
async function sbReq(path,method,body,extra){
  var s=sbSess();
  if(s&&s.exp<Date.now()/1000+60&&s.rt)s=await sbRefresh(s);
  var h=Object.assign({apikey:SB.key,'Content-Type':'application/json'},s?{Authorization:'Bearer '+s.at}:{},extra||{});   /* the new publishable key is not a token, so it goes only in apikey */
  return fetch(SB.url+path,{method:method||'GET',headers:h,body:body==null?undefined:JSON.stringify(body)});
}
async function sbAuth(kind,email,pw){
  var path=kind==='up'?'/auth/v1/signup':'/auth/v1/token?grant_type=password',r,j={};
  try{r=await fetch(SB.url+path,{method:'POST',headers:{apikey:SB.key,'Content-Type':'application/json'},body:JSON.stringify({email:email,password:pw})})}
  catch(e){return {err:__("اینترنت در دسترس نیست","No internet connection")}}
  try{j=await r.json()}catch(e){}
  var s=sbToSess(j);
  if(s)return {s:s};
  if(r.ok&&kind==='up')return {confirm:1};
  return {err:sbErr(j,r.status)};
}
