function vnFmt(s){s=Math.max(0,s||0);var m=Math.floor(s/60),x=Math.floor(s%60);return fa(m+':'+(x<10?'0':'')+x)}
function vnNewId(){return Date.now().toString(36)+Math.random().toString(36).slice(2,6)}
function vnBtnHTML(cls){return '<button type="button" class="vn-btn '+(cls||'')+'" data-m="'+VN.mode+'" aria-label="'+__('ضبط پیام صوتی یا ویدیویی','Record a voice or video message')+'"><span class="vn-bi">'+vnIcon()+'</span></button>'}
function vnIcon(){return VN.mode==='v'?VN_I.cam:VN_I.mic}
function vnSyncBtns(){[].forEach.call(document.querySelectorAll('.vn-btn'),function(b){b.dataset.m=VN.mode;var bi=b.querySelector('.vn-bi');if(bi)bi.innerHTML=vnIcon()})}
function vnMime(video){
  var c=video?['video/webm;codecs=vp8,opus','video/webm;codecs=vp9,opus','video/webm','video/mp4']:['audio/webm;codecs=opus','audio/webm','audio/mp4','audio/ogg;codecs=opus'];
  for(var i=0;i<c.length;i++){try{if(window.MediaRecorder&&MediaRecorder.isTypeSupported(c[i]))return c[i]}catch(e){}}
  return '';
}
function vnWave(p){
  var n=36,out=[],mx=0.05,i,j;
  if(!p||!p.length){for(i=0;i<n;i++)out.push(3);return out}
  p.forEach(function(v){if(v>mx)mx=v});
  for(i=0;i<n;i++){
    var a=Math.floor(i*p.length/n),b=Math.max(a+1,Math.floor((i+1)*p.length/n)),m=0;
    for(j=a;j<b&&j<p.length;j++)if(p[j]>m)m=p[j];
    out.push(Math.max(1,Math.round(m/mx*9)));
  }
  return out;
}
