  var R=VN.rec={btn:o.btn,host:o.host,onSend:o.onSend,dark:o.dark,sx:o.sx,sy:o.sy,side:o.sx>innerWidth/2?1:-1,video:video,chunks:[],peaks:[],acc:0,t0:0,state:'starting',locked:false,facing:'user',torch:false,pst:null,t:performance.now()};
  vcBusy=true;vcT=Date.now();try{if(typeof AO!=='undefined')AO.wk=false;var sp=SRN&&SRN.stop&&SRN.stop();if(sp&&sp.catch)sp.catch(function(){})}catch(e){}
