function vnRelease(R,cancelled){
  if(R.done)return;
  if(R.state==='starting'){
    /* the finger lifted before the microphone/camera was ready (usually the permission box) */
    R.pend={c:!!cancelled};   /* remember the lift; vnStart decides once the permission boxes are done */
    return;
  }
  if(R.locked)return;
  if(cancelled){vnLock(R);return}      /* the system took the touch: keep what was recorded and let the user decide */
  vnEnd(R,true);
}
function vnPause(R){
  if(!R.locked||R.done||!R.mr)return;
  if(R.state==='rec'){R.acc=vnEl(R);R.state='pause';try{R.mr.pause()}catch(e){}R.ov.classList.add('paused')}
  else if(R.state==='pause'){R.t0=performance.now();R.state='rec';try{R.mr.resume()}catch(e){}R.ov.classList.remove('paused')}
  if(R.stt)R.stt.paused=R.state==='pause';
}
/* ---------- understanding what was said: the phone's own speech recogniser listens while the message is recorded ---------- */
function vnSttOn(){try{return localStorage.getItem('ario.vnstt')!=='0'}catch(e){return true}}
async function vnSttPerm(){
  if(!SRN||!vnSttOn())return;
  var pm=await SRN.checkPermissions();
  if(!pm||pm.speechRecognition!=='granted')await SRN.requestPermissions();
}
async function vnSttStart(R){
  if(!SRN||!vnSttOn()||R.stt)return;
  R.hadStt=true;
  var S=R.stt={txt:'',cur:'',run:true,paused:false,done:false,stopped:false,err:0,hs:[]};
  try{
    var pm=await SRN.checkPermissions();
    if(!pm||pm.speechRecognition!=='granted'){S.run=false;S.done=true;R.hadStt=false;return}
    S.hs.push(await SRN.addListener('partialResults',function(x){var m=(x&&x.matches&&x.matches[0])||'';if(m)S.cur=m}));
    try{S.hs.push(await SRN.addListener('listeningState',function(x){if(x&&x.status==='stopped')S.stopped=true}))}catch(e){}
  }catch(e){S.run=false;S.done=true;R.hadStt=false;return}
  (async function(){
    while(S.run){
      if(S.paused){await aoSleep(200);continue}
      S.cur='';S.stopped=false;
      try{await SRN.start({language:EN?'en-US':ARB?'ar-SA':'fa-IR',maxResults:1,partialResults:true,popup:false})}
      catch(e){if(++S.err>=3)break;await aoSleep(500);continue}
      var t0=Date.now();
      while(S.run&&!S.stopped&&!S.paused&&Date.now()-t0<20000)await aoSleep(150);
      if(S.run&&!S.stopped){try{await SRN.stop()}catch(e){}await aoSleep(250)}
      if(S.cur){S.txt+=(S.txt?' ':'')+S.cur;S.cur=''}
      if(S.run)await aoSleep(150);
    }
    S.done=true;
  })();
}
function vnSttStop(R,drop){
  var S=R&&R.stt;if(!S)return Promise.resolve('');
  S.run=false;try{var p=SRN.stop();if(p&&p.catch)p.catch(function(){})}catch(e){}
  return new Promise(function(res){
    var n=0;(function w(){
      if(S.done||n++>14){
        S.hs.forEach(function(h){try{h&&h.remove&&h.remove()}catch(e){}});S.hs=[];
        var t=(S.txt+(S.done||!S.cur?'':' '+S.cur)).replace(/\s+/g,' ').trim();
        R.stt=null;res(drop?'':t.slice(0,800));return}
      setTimeout(w,100);
    })();
  });
}
async function vnFlip(R){
  if(!R.video||R.flipping||R.done)return;R.flipping=true;
  var nf=R.facing==='user'?'environment':'user';
  try{
    var ns=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:nf},width:{ideal:640},height:{ideal:640}}});
    if(R.done){ns.getTracks().forEach(function(t){t.stop()});return}
    R.stream.getVideoTracks().forEach(function(t){t.stop()});
    R.sv.srcObject=ns;try{await R.sv.play()}catch(e){}
    R.vs=ns;R.facing=nf;R.torch=false;R.ov.classList.remove('torch');
  }catch(e){toast(__('دوربین دیگری پیدا نشد','No other camera was found'),null,null,'info')}
  R.flipping=false;
}
function vnTorch(R){
  var tr=(R.vs||R.stream).getVideoTracks()[0];if(!tr)return;
  var on=!R.torch;
  try{
    tr.applyConstraints({advanced:[{torch:on}]}).then(function(){R.torch=on;R.ov.classList.toggle('torch',on)},function(){toast(__('این دوربین چراغ ندارد','This camera has no flash'),null,null,'info')});
  }catch(e){toast(__('این دوربین چراغ ندارد','This camera has no flash'),null,null,'info')}
}
function vnKill(R){
  try{clearInterval(R.tk)}catch(e){}try{cancelAnimationFrame(R.raf)}catch(e){}
  [R.stream,R.vs].forEach(function(s){if(s)s.getTracks().forEach(function(t){try{t.stop()}catch(e){}})});
  try{R.ac&&R.ac.close()}catch(e){}
}
function vnCleanup(R,quick){
  vnKill(R);R.done=true;
  if(VN.rec===R)VN.rec=null;vcBusy=false;
  var o=R.ov;if(o){o.classList.remove('on');o.classList.add(quick?'quick':'out');setTimeout(function(){o.remove()},quick?60:260)}
  setTimeout(function(){try{if(typeof AO!=='undefined'&&!AO.open&&typeof aoWakeStart==='function')aoWakeStart()}catch(e){}},700);
}
function vnFail(R,e){
  R.dead=true;vnSttStop(R,true);vnCleanup(R,true);
  var n=e&&e.name;
  toast(n==='NotAllowedError'||n==='SecurityError'?__('دسترسی به میکروفون یا دوربین بسته است. از تنظیمات گوشی > برنامه‌ها > Ario > مجوزها آن را روشن کن.','Microphone or camera access is off. Turn it on in phone Settings > Apps > Ario > Permissions.'):n==='NotFoundError'?__('میکروفون یا دوربین پیدا نشد.','No microphone or camera was found.'):__('ضبط روی این دستگاه ممکن نشد.','Recording is not possible on this device.'),null,null,'warn');
}
function vnEnd(R,send){
  if(R.done)return;
  var dur=vnEl(R);R.done=true;try{clearInterval(R.tk)}catch(e){}try{cancelAnimationFrame(R.raf)}catch(e){}
  if(R.ov){R.ov.classList.add(send?'sent':'gone')}
  if(R.video&&!R.pst&&send)vnPoster(R);
  function fin(){
    var chunks=R.chunks,mime=R.mime,peak=0,tooShort=dur<0.8||!chunks.length;
    R.peaks.forEach(function(x){if(x>peak)peak=x});
    var heard=R.stt?vnSttStop(R,!send||tooShort):Promise.resolve('');
    vnCleanup(R,false);
    if(!send)return;
    if(tooShort){toast(__('پیام خیلی کوتاه بود؛ برای ضبط دکمه را نگه دارید','Too short. Hold the button to record'),null,null,'info');return}
    heard.then(function(tx){
      /* if the recogniser took the microphone away, the recording itself is silent: switch understanding off so recordings stay safe */
      if(R.hadStt&&peak<0.03&&dur>2){try{localStorage.setItem('ario.vnstt','0')}catch(e){}tx='';toast(__('روی این گوشی فهمیدن حرف‌ها هم‌زمان با ضبط ممکن نیست؛ خاموش شد. می‌توانی از تنظیمات دوباره روشنش کنی.','On this phone understanding speech while recording is not possible, so it was turned off. You can turn it on again in Settings.'),null,null,'info')}
      setTimeout(function(){
        var blob=new Blob(chunks,{type:mime}),pst=R.pst&&R.pst.size?R.pst:null;
        try{R.onSend(blob,{k:R.video?'v':'a',d:Math.round(dur*10)/10,w:vnWave(R.peaks),poster:pst,tx:tx||''})}catch(e){}
      },30);
    });
  }
  if(R.mr&&R.mr.state!=='inactive'){var done=false;R.mr.onstop=function(){if(!done){done=true;fin()}};try{R.mr.stop()}catch(e){if(!done){done=true;fin()}}setTimeout(function(){if(!done){done=true;fin()}},1500)}
  else fin();
}
