      rs0.forEach(function(r,i){if(r.classList.contains('sel'))drop[off0+i]=1});
      kcD().ch[sec]=c.filter(function(m,j){return !drop[j]});persist();vnSweep(old.filter(function(m,j){return drop[j]}));
