/* ---------- v277: «من و مشاور» - a real chat between a counselor and the student linked to him / her ----------
   The first card on the smart-coach page is now «من و آریو» (the local assistant). When a counselor and a student are connected
   (see "counselor <-> student link"), a second card «من و مشاور» appears under it: text, photos, videos, voice / round-video messages,
   files and daily reports go through Supabase (table public.link_messages + private storage bucket "chat", see supabase/setup.sql).
   ui.mcl: '' = closed · '*' = list of chats (more than one link) · <link id> = an open chat.
   The open chat asks the server for new messages every few seconds; the list / card asks every ~half minute. */
var MC={rx:{},rxSig:{},rxOff:0,rxBusy:0,msgs:{},last:{},un:{},unT:0,poll:0,pulling:0,busy:0,lt:0,bl:{},sum:{},draft:{},tray:0,seenAt:0,tick:0};
var MC_MAX=50*1048576;
function mcLinks(){return cnxOn()&&CNX.uid?(CNX.links||[]).filter(function(l){return l.student_id&&(l.counselor_id===CNX.uid||l.student_id===CNX.uid)}):[]}
function mcFriends(){return cnxOn()&&CNX.uid?(CNX.friends||[]).filter(function(l){return l.student_id}):[]}
function mcGroups(){return cnxOn()&&CNX.uid?(CNX.groups||[]):[]}
function mcAll(){return mcLinks().concat(mcFriends(),mcGroups())}
function mcFr(l){return l.kind==='friend'}
function mcGr(l){return !!l&&l.kind==='group'}
function frFlag(){try{return !!localStorage.getItem('ario.fr')}catch(e){return false}}
function mcOpenNow(){return !!ui.mcl&&ui.mcl!=='*'&&ui.mcl!=='#f'}
function mcLink(id){return mcAll().filter(function(l){return l.id===id})[0]||null}
function mcCns(l){return l.counselor_id===CNX.uid}
function mcPeer(l){if(mcGr(l))return l.name||__('گروه','Group');if(mcFr(l))return (mcCns(l)?l.student_name:l.counselor_name)||__('دوست','Friend');return mcCns(l)?(l.student_name||__('دانش‌آموز','Student')):(l.counselor_name||__('مشاور','Advisor'))}
function mcIni(l){if(mcGr(l))return Array.from(String(l.name||'گ'))[0]||'گ';if(mcFr(l))return String(mcPeer(l)).trim().charAt(0)||'د';return mcCns(l)?(String(mcPeer(l)).trim().charAt(0)||'د'):'م'}
/* ----- Telegram-style profile picture beside the other person's bubbles ----- */
function mcHue(n){var h=0,i;n=String(n||'');for(i=0;i<n.length;i++)h=(h*31+n.charCodeAt(i))%360;return h}
function mcMyAv(){var p=state.profile,n=String(displayName()||'');return {p:okPhoto(p.photo)&&!isVip(p.photo)?p.photo:'',v:okPhoto(p.photo)&&canUse(p.photo)?p.photo:'',h:isFinite(+p.hue)&&p.hue!=null?+p.hue:mcHue(n),n:Array.from(n)[0]||''}}
/* every message carries the sender's picture (a built-in photo id / colour and first letter), so no extra upload is needed */
function mcPeerAv(l){
  var a=MC.msgs[l.id]||[],i,nm=String(mcPeer(l)),v;
  for(i=a.length-1;i>=0;i--){if(a[i].sender_id!==CNX.uid&&a[i].meta&&a[i].meta.av){v=a[i].meta.av;return {p:okPhoto(v.p)&&!isVip(v.p)?v.p:'',h:isFinite(+v.h)?+v.h:mcHue(nm),n:Array.from(String(v.n||nm))[0]||''}}}
  return {p:'',h:mcHue(nm),n:Array.from(nm)[0]||''};
}
function mcSnd(l,m){var ms=(l&&l.members)||[],i;for(i=0;i<ms.length;i++)if(ms[i].user_id===m.sender_id&&ms[i].name)return ms[i].name;return (m.meta&&m.meta.nm)||__('عضو','Member')}
function mcMsgAv(m,nm){var v=(m.meta&&m.meta.av)||{};return {p:okPhoto(v.p)&&!isVip(v.p)?v.p:'',h:isFinite(+v.h)&&v.h!=null?+v.h:mcHue(nm),n:Array.from(String(v.n||nm))[0]||''}}
function mcAvHTMLv(v){return '<i class="mc-av" aria-hidden="true" style="--h:'+v.h+'">'+(v.p?'<span class="aimg '+v.p+'"></span>':'<b>'+esc(v.n)+'</b>')+'</i>'}
function mcAvHTML(l){var v=mcPeerAv(l);return '<i class="mc-av" aria-hidden="true" style="--h:'+v.h+'">'+(v.p?'<span class="aimg '+v.p+'"></span>':'<b>'+esc(v.n)+'</b>')+'</i>'}
/* only the last bubble of a run shows the picture (the others keep the space) */
function mcAvFix(){
  var th=document.getElementById('mcTh');if(!th)return;
  var rows=th.children,i,n;
  /* v308: messages of one sender within 5 minutes form a stack: g-p = continues the one above, g-n = the next one continues it */
  var same=function(a,b){return !!(a&&b&&a.classList.contains('kcx-row')&&b.classList.contains('kcx-row')&&a.dataset.snd===b.dataset.snd&&Math.abs(a.dataset.t-b.dataset.t)<300000)};
  for(i=0;i<rows.length;i++){if(rows[i].classList.contains('kcx-row')){rows[i].classList.toggle('g-p',same(rows[i-1],rows[i]));rows[i].classList.toggle('g-n',same(rows[i],rows[i+1]))}}
  for(i=0;i<rows.length;i++){if(!rows[i].classList.contains('mc-hasav'))continue;n=rows[i+1];rows[i].classList.toggle('mc-av-on',!(n&&n.classList.contains('mc-hasav')&&n.dataset.snd===rows[i].dataset.snd))}
}
function mcTitle(){var ls=mcLinks();return ls.some(function(l){return !mcCns(l)})?__('من و مشاور','Me & my advisor'):__('من و دانش‌آموزان','Me & my students')}
function mcNewId(){
  try{if(crypto.randomUUID)return crypto.randomUUID()}catch(e){}
  var a=new Uint8Array(16),h;crypto.getRandomValues(a);a[6]=a[6]&15|64;a[8]=a[8]&63|128;
  h=[].map.call(a,function(x){return (x+256).toString(16).slice(1)}).join('');
  return h.slice(0,8)+'-'+h.slice(8,12)+'-'+h.slice(12,16)+'-'+h.slice(16,20)+'-'+h.slice(20);
}
function mcMs(s){var t=Date.parse(s);return isNaN(t)?0:t}
function mcSort(a){a.sort(function(x,y){return mcMs(x.created_at)-mcMs(y.created_at)||(x.id<y.id?-1:1)})}
function mcUnTotal(){var n=0,ok={};mcLinks().forEach(function(l){ok[l.id]=1});for(var k in MC.un)if(ok[k])n+=MC.un[k]||0;return n}
function mcUnAll(){var n=0;for(var k in MC.un)n+=MC.un[k]||0;return n}

/* ----- storage (private bucket "chat") ----- */
async function mcTok(){var s=sbSess();if(s&&s.exp<Date.now()/1000+60&&s.rt)s=await sbRefresh(s);return s&&s.at||''}
function mcPathEnc(p){return String(p).split('/').map(encodeURIComponent).join('/')}
/* nc = do not keep the file in memory afterwards (big videos / files) */
function mcBlob(path,nc){
  if(!path)return Promise.reject(new Error('nopath'));
  if(MC.bl[path])return MC.bl[path];
  var p=(async function(){
    var t=await mcTok(),r=await fetch(SB.url+'/storage/v1/object/authenticated/chat/'+mcPathEnc(path),{headers:{apikey:SB.key,Authorization:'Bearer '+t}});
    if(!r.ok)throw new Error('dl '+r.status);
    var b=await r.blob();return {b:b,u:URL.createObjectURL(b)};
  })();
  if(!nc){MC.bl[path]=p;p.catch(function(){delete MC.bl[path]})}
  return p;
}
async function mcPut(path,blob){
  var t=await mcTok(),ty=String(blob.type||'application/octet-stream').split(';')[0]||'application/octet-stream';
  var r=await fetch(SB.url+'/storage/v1/object/chat/'+mcPathEnc(path),{method:'POST',headers:{apikey:SB.key,Authorization:'Bearer '+t,'Content-Type':ty,'x-upsert':'false'},body:blob});
  if(!r.ok){
    var tx='';try{tx=await r.text()}catch(x){}
    if(r.status===409||/duplicate|already exists/i.test(tx))return;      /* a retry after the file was already stored */
    var e=new Error('up '+r.status+' '+tx.slice(0,80));e.st=r.status;throw e;
  }
}
function mcExt(blob,name){
  var m=/\.([a-z0-9]{1,6})$/i.exec(name||'');if(m)return m[1].toLowerCase();
  var t=String(blob&&blob.type||'').split(';')[0],M={'image/jpeg':'jpg','image/png':'png','image/webp':'webp','video/mp4':'mp4','video/webm':'webm','video/quicktime':'mov','audio/webm':'webm','audio/mp4':'m4a','audio/ogg':'ogg','application/pdf':'pdf'};
  return M[t]||'bin';
}
function mcSize(n){n=+n||0;return n>=1048576?fa((Math.round(n/104857.6)/10))+' MB':fa(Math.max(1,Math.round(n/1024)))+' KB'}
async function mcSave(blob,name){
  var FS=capGet('Filesystem'),SH=capGet('Share');
  if(FS&&SH){
    try{
      var b64=await new Promise(function(res,rej){var fr=new FileReader();fr.onload=function(){res(String(fr.result).split(',')[1])};fr.onerror=rej;fr.readAsDataURL(blob)});
      var r=await FS.writeFile({path:name,data:b64,directory:'CACHE'});
      await SH.share({title:name,url:r.uri,dialogTitle:__('ذخیره یا ارسال فایل','Save or share the file')});return;
    }catch(e){if(/cancel/i.test(String(e&&e.message||e)))return}
  }
  var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;
  document.body.appendChild(a);a.click();setTimeout(function(){URL.revokeObjectURL(a.href);a.remove()},4000);
}

/* ----- texts ----- */
function mcPrev(m){
  if(!m)return '';
  var t=m.kind==='s'?'🧸 '+__('استیکر','Sticker'):m.kind==='p'?'📷 '+__('عکس','Photo'):m.kind==='v'?'🎥 '+__('ویدیو','Video'):m.kind==='a'?'🎤 '+__('پیام صوتی','Voice message'):m.kind==='r'?'🎥 '+__('پیام ویدیویی','Video message'):m.kind==='f'?(m.meta&&m.meta.t==='note'?'📝 ':m.meta&&m.meta.t==='fc'?'🗂 ':'📎 ')+(lsTitle(m)):m.kind==='g'?'📝 '+__('گزارش‌کار روزانه','Daily report'):m.kind==='q'?'📊 '+String(m.body||'').replace(/\s+/g,' ').slice(0,60):String(m.body||'').replace(/\s+/g,' ').slice(0,80);
  var gl=mcLink(m.link_id);
  return (m.sender_id===CNX.uid?__('تو: ','You: '):mcGr(gl)?mcSnd(gl,m)+': ':'')+t;
}
function mcErrMsg(e){
  var st=e&&e.st;
  if(st===404||st===400&&/bucket/i.test(String(e&&e.message||'')))return __('جدول یا فضای فایل گفتگو هنوز در Supabase ساخته نشده (بخش v277 فایل supabase/setup.sql را اجرا کن).','The chat table or storage is not in Supabase yet (run the v277 block of supabase/setup.sql).');
  if(e&&e.off)return __('اینترنت در دسترس نیست','No internet connection');
  return __('ارسال نشد؛ دوباره امتحان کن','Not sent; try again');
}

