/* v337: the ⋮ button at the top-left of «من و آریو», «من و مشاور» and the chats page (friends / groups) - a small menu that drops down from it */
var HD_DOTS='<svg viewBox="0 0 24 24" class="ic" aria-hidden="true"><circle cx="12" cy="5.5" r="1.7" fill="currentColor" stroke="none"/><circle cx="12" cy="12" r="1.7" fill="currentColor" stroke="none"/><circle cx="12" cy="18.5" r="1.7" fill="currentColor" stroke="none"/></svg>';
function hdDots(k){return '<button type="button" class="round glass hd-dots" data-act="hdMenu" data-k="'+k+'" aria-haspopup="menu" aria-label="'+__('بیشتر','More')+'">'+HD_DOTS+'</button>'}
function hdItems(k){
  var on=cnxOn(),refresh=['refresh',icon('refresh'),'#0ea5a4,#34d3c9',__('به‌روزرسانی گفتگوها','Refresh chats')];
  if(!on)return [['login',icon('mail'),'#3d8fe3,#63b0f2',__('ورود با ایمیل','Sign in with email')]];
  if(k==='f')return [
    ['grp',FR_SVG.grp,'#3d8fe3,#63b0f2',__('ساخت گروه','New group')],
    ['bulk',FR_SVG.bulk,'#3fae4a,#6fcf6a',__('پیام به چند دوست','Message several')],
    ['mk',icon('plus'),'#f08a24,#f7b24a',__('ساخت کد دوستی','Make a friend code')],
    ['enter',icon('pen'),'#8a5cf0,#b08cff',__('نوشتن کد دوستم','Write my friend’s code')],
    refresh];
  if(k==='m')return [
    ['ario',icon('chat'),'#34d399,#0f9d74',__('من و آریو','Me & Ario')],
    refresh];
  var it=[];
  if(mcLinks().length)it.push(['adv',icon('chat'),'#38bdf8,#2563eb',mcTitle()]);
  it.push(refresh);
  return it;
}
actions.hdMenu=function(d,el){
  if(document.getElementById('frPop')){frPopClose();return}
  var b=el||document.querySelector('.hd-dots');if(!b)return;
  var r=b.getBoundingClientRect(),items=hdItems(d.k);
  var p=document.createElement('div');p.id='frPop';p.className='fr-pop hd-pop';
  p.innerHTML='<div class="fr-scrim"></div><div class="fr-menu" role="menu" style="top:'+Math.round(r.bottom+8)+'px">'+items.map(function(x){
    return '<button type="button" class="fr-mi" role="menuitem" data-k="'+x[0]+'"><i class="fr-mic" style="background:linear-gradient(145deg,'+x[2]+')">'+x[1]+'</i><span>'+x[3]+'</span></button>';
  }).join('')+'</div>';
  p.addEventListener('click',function(e){
    var m=e.target.closest('.fr-mi');
    if(!m){frPopClose();return}
    var k=m.dataset.k;frPopClose();hap('sel');
    if(k==='grp')actions.grNew();else if(k==='bulk')actions.grBulk();else if(k==='mk')actions.frMake();
    else if(k==='enter'){FR_ENTER=1;actions.frAdd()}
    else if(k==='login')actions.mcLogin();
    else if(k==='ario')actions.kcAdv();
    else if(k==='adv')actions.mcCard();
    else if(k==='refresh'){mcRefresh(true);toast(__('در حال به‌روزرسانی…','Refreshing…'),null,null,'ok')}
  });
  document.body.appendChild(p);
};
actions.mcLogin=function(){sbSheet()};
actions.frMake=async function(){
  var s=sbSess();if(!s)return;
  frMsg(__('در حال ساخت کد…','Making the code…'));
  var r,i;
  for(i=0;i<3;i++){
    r=await cnxReq('/rest/v1/friend_links','POST',{code:cnxNewCode(),owner_id:s.uid,owner_name:String(displayName()).slice(0,80)},{Prefer:'return=representation'});
    if(r.ok||r.st!==409)break;
  }
  if(!r.ok){frMsg(r.st===404?__('جدول دوستی هنوز در Supabase ساخته نشده (بخش v279 فایل supabase/setup.sql را اجرا کن).','The friend table is not in Supabase yet (run the v279 block of supabase/setup.sql).'):cnxNetErr(r),1);return}
  frMsg(__('کد ساخته شد؛ برای دوستت بفرستش.','Code made; send it to your friend.'));
  await cnxLoad();mcCardPaint();
  var c=r.j&&r.j[0]&&r.j[0].code;if(c)actions.frShare({code:c});
};
actions.frShare=async function(d){
  var t=__('بیا در Ario با هم چت کنیم! کد دوستی من: ','Let’s chat on Ario! My friend code: ')+d.code+'\n'+__('در برنامه: حساب ← روی بنر پروفایل ۲ بار سمت راست و ۳ بار سمت چپ بزن ← کد را وارد کن.','In the app: Account → tap the profile banner twice on the right and three times on the left → enter the code.');
  try{var SH=capGet('Share');if(SH){await SH.share({text:t,dialogTitle:__('ارسال کد دوستی','Share the friend code')});return}}catch(e){if(/cancel/i.test(String(e&&e.message||e)))return}
  try{if(navigator.share){await navigator.share({text:t});return}}catch(e){if(e&&e.name==='AbortError')return}
  try{await navigator.clipboard.writeText(t);toast(__('کد کپی شد','Code copied'),null,null,'info')}catch(e){toast(d.code,null,null,'info')}
};
actions.frGo=async function(){
  var inp=document.getElementById('frCode'),code=cnxNormCode(inp?inp.value:'');
  if(code.length!==8){frMsg(__('کد ۸ حرفی است؛ دوباره نگاه کن.','The code has 8 characters; check it again.'),1);return false}
  frMsg(__('در حال اتصال…','Connecting…'));
  var r=await cnxReq('/rest/v1/rpc/redeem_friend','POST',{p_code:code,p_name:String(displayName()).slice(0,80)});
  if(!r.ok){frMsg(r.st===404?__('تابع دوستی هنوز در Supabase ساخته نشده (بخش v279 فایل supabase/setup.sql را اجرا کن).','The friend function is not in Supabase yet (run the v279 block of supabase/setup.sql).'):cnxNetErr(r),1);return false}
  var j=r.j||{};
  if(!j.ok){var M={notfound:__('این کد پیدا نشد.','Code not found.'),self:__('این کد را خودت ساخته‌ای؛ آن را به دوستت بده.','You made this code yourself; give it to your friend.'),used:__('این کد قبلاً استفاده شده.','This code is already used.'),expired:__('این کد منقضی شده؛ یک کد تازه بخواه.','This code expired; ask for a new one.')};frMsg(M[j.err]||cnxNetErr(r),1);return false}
  if(inp)inp.value='';
  frMsg(__('وصل شدی به ','Connected to ')+(j.owner_name||__('دوستت','your friend'))+'.');
  await cnxLoad();mcCardPaint();hap('send');mcFriends().forEach(mcCfOnce);mcConfetti();
  return true;
};
actions.frDel=function(d){
  askConfirm({title:__('قطع ارتباط؟','End the link?'),msg:__('همهٔ پیام‌های این گفتگو برای هر دو نفر پاک می‌شود.','All messages of this chat are deleted for both of you.'),btns:[{t:__('قطع ارتباط','End the link'),cls:'bad',fn:async function(){
    var r=await cnxReq('/rest/v1/friend_links?id=eq.'+encodeURIComponent(d.id),'DELETE',null,{Prefer:'return=minimal'});
    if(!r.ok){frMsg(cnxNetErr(r),1);return}
    delete MC.msgs[d.id];delete MC.sum[d.id];delete MC.un[d.id];
    await cnxLoad();mcCardPaint();
  }}]});
};

/* ---------- v296: groups + one message to several friends ----------
   A group is one more kind of chat (kind:'group'); its id is the link_id of its messages (see the v296 block of supabase/setup.sql).
   CNX.groups = [{id,name,counselor_id:owner,members:[{user_id,name,last_read}],lr:my last_read}]. In a group "unread" is counted from lr. */
function grFriends(){return mcFriends().map(function(l){var u=mcCns(l)?l.student_id:l.counselor_id;return {id:u,name:mcPeer(l),link:l}})}
function grHue(n){return mcHue(n)}
/* v304: the group's picture = one of the built-in (non-VIP) avatars picked by the owner; without one the first letter is shown */
/* v305: the photo may also be a small square JPEG from the gallery, stored as a data URL (see group_set_photo in supabase/setup.sql) */
function grIsData(p){return typeof p==='string'&&p.length<24000&&/^data:image\/jpeg;base64,[A-Za-z0-9+\/=]{20,}$/.test(p)}
function grPhoto(g){var p=g&&g.photo;if(grIsData(p))return p;return okPhoto(p)&&!isVip(p)?p:''}
function grAvIn(g){var p=grPhoto(g);if(!p)return esc(mcIni(g));return grIsData(p)?'<span class="aimg" style="background-image:url('+p+')"></span>':'<span class="aimg '+p+'"></span>'}
/* v305: pick a picture from the gallery -> centred square, 144px, JPEG (about 6-10 KB). Resolves '' when cancelled or unreadable. */
function grPickImage(){
  return new Promise(function(res){
    var inp=document.createElement('input'),done=0;inp.type='file';inp.accept='image/*';inp.style.display='none';document.body.appendChild(inp);
    function fin(v){if(done)return;done=1;try{inp.remove()}catch(e){}res(v||'')}
    inp.addEventListener('change',function(){
      var f=inp.files&&inp.files[0];if(!f){fin('');return}
      var url=URL.createObjectURL(f),im=new Image();
      im.onload=function(){
        try{
          var S=144,cv=document.createElement('canvas');cv.width=cv.height=S;
          var w=im.naturalWidth,h=im.naturalHeight,m=Math.min(w,h),c=cv.getContext('2d');
          c.fillStyle='#fff';c.fillRect(0,0,S,S);
          c.drawImage(im,(w-m)/2,(h-m)/2,m,m,0,0,S,S);
          var d=cv.toDataURL('image/jpeg',.72);
          URL.revokeObjectURL(url);fin(grIsData(d)?d:'');
        }catch(e){fin('')}
      };
      im.onerror=function(){URL.revokeObjectURL(url);fin('')};
      im.src=url;
    });
    inp.addEventListener('cancel',function(){fin('')});
    inp.click();
  });
}
function grCamHTML(ph){return ph?'<span class="aimg" style="background-image:url('+ph+')"></span>':icon('camera')}
function grPickHTML(list,on){
  return list.map(function(f){
    return '<label class="gr-pk"><input type="checkbox" value="'+esc(f.id)+'"'+(on.indexOf(f.id)>-1?' checked':'')+'><i class="gr-av" style="--h:'+grHue(f.name)+'">'+esc(Array.from(String(f.name||'د'))[0]||'د')+'</i><span dir="auto">'+esc(f.name)+'</span></label>';
  }).join('');
}
function grChecked(root){return [].map.call(root.querySelectorAll('.gr-list input:checked'),function(i){return i.value})}
function grErrText(j){
  var M={name:__('نام گروه را بنویس.','Write a group name.'),members:__('حداقل یک دوست انتخاب کن.','Pick at least one friend.'),notfriend:__('فقط دوستان اتصال‌شده را می‌شود اضافه کرد.','Only linked friends can be added.'),full:__('گروه پر است (حداکثر ۵۰ نفر).','The group is full (50 people at most).'),owner:__('فقط مدیر یا ادمین‌های گروه می‌توانند این کار را بکنند.','Only the group owner or an admin can do this.'),admin:__('ادمین نمی‌تواند ادمین دیگر را حذف کند.','An admin cannot remove another admin.'),member:__('این شخص عضو گروه نیست.','This person is not in the group.'),self:__('خودت را نمی‌شود حذف کرد؛ از «ترک گروه» استفاده کن.','You cannot remove yourself; use “Leave group”.')};
  return M[j&&j.err]||__('انجام نشد. دوباره امتحان کن','That did not work. Try again');
}
function grNoTable(r){return r&&r.st===404?__('بخش گروه هنوز در Supabase ساخته نشده (بخش v296 فایل supabase/setup.sql را اجرا کن).','Groups are not in Supabase yet (run the v296 block of supabase/setup.sql).'):''}
function grRowHTML(l){
  var s=MC.sum[l.id],u=MC.un[l.id]||0;
  return '<button type="button" class="kc-topic mc-row" data-act="mcOpen" data-from="#f" data-id="'+esc(l.id)+'"><span class="kc-tt"><b><i class="kc-ph'+(grPhoto(l)?' has-p':'')+'" style="background:linear-gradient(145deg,#34d399,#0f9d6e)">'+grAvIn(l)+'</i>'+esc(mcPeer(l))+(u?'<span class="un-b" role="status">'+fa(u>99?99:u)+'</span>':'')+'</b><small>'+(s?kcxTime(s.created_at):'')+'</small></span><span class="kc-tpv">'+esc(s?mcPrev(s):fa(l.members.length)+' '+__('عضو','members'))+'</span></button>';
}
function grSheet(title,inner,okTxt){
  var sw=ttSheetWrap('<div class="sheet-top"><span></span><h2>'+title+'</h2><button type="button" data-gr="close">'+__('بستن','Close')+'</button></div><div class="gr-body">'+inner+'<div class="cx-msg" id="grMsg" role="status"></div>'+(okTxt?'<button type="button" class="tt-btn pri cx-mk" data-gr="ok">'+okTxt+'</button>':'')+'</div>',title);
  sw.w.classList.add('gr-wrap');
  sw.msg=function(t,bad){var m=sw.w.querySelector('#grMsg');if(m){m.textContent=t||'';m.className='cx-msg'+(bad?' bad':'')}};
  return sw;
}
actions.grNew=function(){
  var fl=grFriends();
  if(!fl.length){toast(__('اول یک دوست اضافه کن (کد دوستی).','Add a friend first (friend code).'),null,null,'warn');return}
  if(document.querySelector('.gr-wrap'))return;
  var sw=grSheet(__('گروه جدید','New group'),'<div class="gr-nm"><button type="button" class="gr-cam" data-gr="cam" aria-label="'+__('عکس گروه','Group photo')+'">'+grCamHTML('')+'</button><input class="field" id="grName" maxlength="60" dir="auto" autocomplete="off" placeholder="'+__('نام گروه','Group name')+'"></div><button type="button" class="tt-btn gr-nophoto" data-gr="camrm" hidden>'+__('حذف عکس','Remove photo')+'</button><p class="hint2">'+__('اعضا را از بین دوستانت انتخاب کن','Pick the members from your friends')+'</p><div class="gr-list">'+grPickHTML(fl,[])+'</div>',__('ساخت گروه','Create group'));
  var busy=0,gph='';
  function camPaint(){var c=sw.w.querySelector('.gr-cam'),r=sw.w.querySelector('.gr-nophoto');if(c)c.innerHTML=grCamHTML(gph);if(r)r.hidden=!gph}
  sw.w.addEventListener('click',async function(e){
    var b=e.target.closest('[data-gr]');if(!b)return;
    if(b.dataset.gr==='close'){sw.close();return}
    if(b.dataset.gr==='cam'){var d=await grPickImage();if(d){gph=d;camPaint()}else if(!gph)sw.msg(__('عکس انتخاب نشد.','No photo was picked.'));return}
    if(b.dataset.gr==='camrm'){gph='';camPaint();return}
    if(b.dataset.gr!=='ok'||busy)return;
    var nm=sw.w.querySelector('#grName').value.trim(),ids=grChecked(sw.w);
    if(!nm){sw.msg(grErrText({err:'name'}),1);return}
    if(!ids.length){sw.msg(grErrText({err:'members'}),1);return}
    busy=1;b.disabled=true;sw.msg(__('در حال ساخت…','Creating…'));
    var r=await cnxReq('/rest/v1/rpc/create_group','POST',{p_name:nm,p_members:ids,p_my_name:String(displayName()).slice(0,80)});
    busy=0;b.disabled=false;
    if(!r.ok){sw.msg(grNoTable(r)||cnxNetErr(r),1);return}
    var j=r.j||{};if(!j.ok){sw.msg(grErrText(j),1);return}
    if(gph&&j.id){/* v305: the gallery photo is saved right after the group exists */
      var pr=await cnxReq('/rest/v1/rpc/group_set_photo','POST',{p_group:j.id,p_photo:gph});
      if(!pr.ok||!(pr.j&&pr.j.ok))toast(pr.st===404?__('گروه ساخته شد ولی عکس ذخیره نشد (بخش v305 فایل supabase/setup.sql را اجرا کن).','Group created, but the photo was not saved (run the v305 block of supabase/setup.sql).'):__('گروه ساخته شد ولی عکس ذخیره نشد؛ از اطلاعات گروه دوباره امتحان کن.','Group created, but the photo was not saved; try again from Group info.'),null,null,'warn');
    }
    await cnxLoad();sw.close();mcCardPaint();hap('send');
    if(j.id)mcOpenChat(j.id,'#f');
  });
};
actions.grBulk=function(){
  var fl=grFriends();
  if(!fl.length){toast(__('اول یک دوست اضافه کن (کد دوستی).','Add a friend first (friend code).'),null,null,'warn');return}
  if(document.querySelector('.gr-wrap'))return;
  var sw=grSheet(__('پیام به چند دوست','Message several friends'),'<p class="hint2">'+__('یک پیام برای هر دوستی که انتخاب کنی جدا فرستاده می‌شود؛ جواب‌ها هم جدا می‌آید.','The message goes to each chosen friend on their own; their replies come back separately.')+'</p><button type="button" class="tt-btn gr-all" data-gr="all">'+__('انتخاب همه','Select all')+'</button><div class="gr-list">'+grPickHTML(fl,[])+'</div><textarea class="field" id="grText" rows="4" maxlength="3000" dir="auto" placeholder="'+__('پیام','Message')+'"></textarea>',__('ارسال','Send'));
  sw.w.addEventListener('click',function(e){
    var b=e.target.closest('[data-gr]');if(!b)return;
    var k=b.dataset.gr;
    if(k==='close'){sw.close();return}
    if(k==='all'){var ins=sw.w.querySelectorAll('.gr-list input'),all=[].every.call(ins,function(i){return i.checked});[].forEach.call(ins,function(i){i.checked=!all});return}
    if(k!=='ok')return;
    var t=sw.w.querySelector('#grText').value.trim(),ids=grChecked(sw.w);
    if(!ids.length){sw.msg(grErrText({err:'members'}),1);return}
    if(!t){sw.msg(__('پیام را بنویس.','Write the message.'),1);return}
    var by={},n=0;grFriends().forEach(function(f){by[f.id]=f.link});
    ids.forEach(function(id){if(by[id]&&mcSendText(by[id],t))n++});
    sw.close();
    toast(__('پیام برای ','Message sent to ')+fa(n)+' '+__('دوست فرستاده شد','friends'),null,null,'ok');
  });
};
/* the group's own page: members, rename, add / remove (owner), mute, leave */
function grpInfo(l){
  if(document.querySelector('.gr-info'))return;
  var id=l.id;
  var sw=grSheet(__('اطلاعات گروه','Group info'),'<div class="gr-ib"></div>','');
  sw.w.classList.add('gr-info');
  var box=sw.w.querySelector('.gr-ib');
  function paint(){
    var g=mcLink(id);if(!g){sw.close();return}
    var own=mcCns(g),ms=g.members||[];
    var h='<div class="gr-hd"><i class="gr-av big'+(grPhoto(g)?' has-p':'')+'" style="--h:'+grHue(g.name)+'">'+grAvIn(g)+'</i><b dir="auto">'+esc(g.name)+'</b><small>'+fa(ms.length)+' '+__('عضو','members')+'</small>'+(own?'<span class="gr-ph"><button type="button" class="tt-btn" data-gr="photo">'+icon('edit')+__('انتخاب عکس گروه','Choose group photo')+'</button><button type="button" class="tt-btn" data-gr="gal">'+icon('img')+__('از گالری','From gallery')+'</button>'+(grPhoto(g)?'<button type="button" class="tt-btn" data-gr="nophoto">'+__('حذف عکس','Remove photo')+'</button>':'')+'</span>':'')+'</div>';
    if(own)h+='<div class="gr-ren"><input class="field" id="grRen" maxlength="60" dir="auto" value="'+esc(g.name)+'" aria-label="'+__('نام گروه','Group name')+'"><button type="button" class="tt-btn" data-gr="ren">'+__('ذخیره نام','Save name')+'</button></div>';
    h+='<div class="sec-h"><b>'+__('اعضا','Members')+'</b></div><div class="gr-mems">'+ms.map(function(m){
      var me=m.user_id===CNX.uid,nm=m.name||__('عضو','Member');
      return '<div class="gr-mr" data-gr="mp" data-u="'+esc(m.user_id)+'" role="button" tabindex="0">'+grMemAvHTML(g,m)+'<span dir="auto">'+esc(nm)+(me?' ('+__('تو','you')+')':'')+'</span>'+(m.user_id===g.counselor_id?'<em>'+__('مدیر','Owner')+'</em>':'')+(own&&!me?'<button type="button" class="mc-x" data-gr="rm" data-u="'+esc(m.user_id)+'" aria-label="'+__('حذف از گروه','Remove')+'">'+icon('close')+'</button>':'')+'</div>';
    }).join('')+'</div>';
    h+='<div class="mc-gact">'+(own?'<button type="button" class="tt-btn pri" data-gr="add">'+icon('plus')+__('افزودن عضو','Add member')+'</button>':'')+'<button type="button" class="tt-btn" data-gr="mute">'+(mcMuted(id)?__('صدا را باز کن','Unmute'):__('بی‌صدا','Mute'))+'</button><button type="button" class="tt-btn bad" data-gr="leave">'+__('ترک گروه','Leave group')+'</button></div>';
    box.innerHTML=h;
    if(window.gpgRefresh)window.gpgRefresh();
  }
  paint();
  async function after(r,okMsg){
    if(!r.ok){sw.msg(grNoTable(r)||cnxNetErr(r),1);return false}
    var j=r.j||{};if(!j.ok){sw.msg(grErrText(j),1);return false}
    await cnxLoad();sw.msg(okMsg||'');paint();mcCardPaint();return true;
  }
  sw.w.addEventListener('click',async function(e){
    var b=e.target.closest('[data-gr]');if(!b)return;
    var k=b.dataset.gr,g=mcLink(id);if(!g&&k!=='close')return;
    if(k==='close'){sw.close();return}
    if(k==='mute'){mcMuteSet(id,!mcMuted(id));paint();return}
    if(k==='mp'){var pm=grMember(g,b.dataset.u);mcpOpen(g,{uid:b.dataset.u,name:pm&&pm.name});return}
    if(k==='photo'||k==='nophoto'||k==='gal'){
      var setP=async function(ph,done){
        var r=await cnxReq('/rest/v1/rpc/group_set_photo','POST',{p_group:id,p_photo:ph});
        if(!r.ok&&r.st===404){(done||sw).msg(__('عکس گروه هنوز در Supabase ساخته نشده (بخش v304 فایل supabase/setup.sql را اجرا کن).','Group photos are not in Supabase yet (run the v304 block of supabase/setup.sql).'),1);return false}
        var ok=await after(r,ph?__('عکس گروه عوض شد.','Group photo changed.'):__('عکس گروه برداشته شد.','Group photo removed.'));
        if(ok&&ui.tab==='kcm')render('swap');
        return ok;
      };
      if(k==='nophoto'){await setP('');return}
      if(k==='gal'){var gd=await grPickImage();if(!gd){sw.msg(__('عکس انتخاب نشد.','No photo was picked.'),1);return}sw.msg(__('در حال ذخیره…','Saving…'));await setP(gd);return}
      if(document.querySelector('.gr-pick'))return;
      var s3=grSheet(__('عکس گروه','Group photo'),'<div class="avgrid" id="grAvs">'+Object.keys(AVN).filter(function(a){return !isVip(a)}).map(function(a){return '<button type="button" class="avo" data-av="'+a+'" aria-pressed="'+(grPhoto(g)===a)+'" aria-label="'+AVN[a]+'"><span class="aimg '+a+'"></span></button>'}).join('')+'</div>','');
      s3.w.classList.add('gr-pick');
      s3.w.addEventListener('click',async function(ev){
        var c=ev.target.closest('[data-gr]');if(c&&c.dataset.gr==='close'){s3.close();return}
        var a=ev.target.closest('[data-av]');if(!a)return;
        a.disabled=true;
        var ok=await setP(a.dataset.av,s3);
        a.disabled=false;
        if(ok)s3.close();
      });
      return;
    }
    if(k==='ren'){
      var nm=sw.w.querySelector('#grRen').value.trim();if(!nm){sw.msg(grErrText({err:'name'}),1);return}
      if(await after(await cnxReq('/rest/v1/rpc/group_rename','POST',{p_group:id,p_name:nm}),__('نام عوض شد.','Name changed.'))&&ui.tab==='kcm')render('swap');
      return;
    }
    if(k==='rm'){
      var mm=(g.members||[]).filter(function(x){return x.user_id===b.dataset.u})[0];
      askConfirm({title:__('حذف از گروه؟','Remove from the group?'),msg:(mm&&mm.name||'')+' '+__('دیگر پیام‌های گروه را نمی‌بیند.','will no longer see the group’s messages.'),btns:[{t:__('حذف','Remove'),cls:'bad',fn:async function(){await after(await cnxReq('/rest/v1/rpc/group_remove','POST',{p_group:id,p_user:b.dataset.u}))}}]});
      return;
    }
    if(k==='add'){
      var have=(g.members||[]).map(function(x){return x.user_id}),cand=grFriends().filter(function(f){return have.indexOf(f.id)<0});
      if(!cand.length){sw.msg(__('همه‌ی دوستانت در گروه هستند.','All your friends are already in the group.'));return}
      var s2=grSheet(__('افزودن عضو','Add member'),'<div class="gr-list">'+grPickHTML(cand,[])+'</div>',__('افزودن','Add'));
      s2.w.addEventListener('click',async function(ev){
        var c=ev.target.closest('[data-gr]');if(!c)return;
        if(c.dataset.gr==='close'){s2.close();return}
        if(c.dataset.gr!=='ok')return;
        var ids=grChecked(s2.w);if(!ids.length){s2.msg(grErrText({err:'members'}),1);return}
        c.disabled=true;var bad=null,i,r;
        for(i=0;i<ids.length;i++){r=await cnxReq('/rest/v1/rpc/group_add','POST',{p_group:id,p_user:ids[i]});if(!r.ok||!(r.j&&r.j.ok)){bad=r;break}}
        c.disabled=false;
        if(bad){s2.msg(grNoTable(bad)||(bad.ok?grErrText(bad.j):cnxNetErr(bad)),1);return}
        await cnxLoad();s2.close();paint();mcCardPaint();if(ui.tab==='kcm')render('swap');
      });
      return;
    }
    if(k==='leave'){
      askConfirm({title:__('ترک گروه؟','Leave the group?'),msg:__('دیگر پیام‌های این گروه را نمی‌بینی.','You will no longer see this group’s messages.'),btns:[{t:__('ترک گروه','Leave'),cls:'bad',fn:async function(){
        var r=await cnxReq('/rest/v1/rpc/group_leave','POST',{p_group:id});
        if(!r.ok||!(r.j&&r.j.ok)){sw.msg(grNoTable(r)||(r.ok?grErrText(r.j):cnxNetErr(r)),1);return}
        delete MC.msgs[id];delete MC.sum[id];delete MC.un[id];delete MC.last[id];
        await cnxLoad();sw.close();mcStop();
        ui.mcl='#f';ui.mcFrom='';render('enter');window.scrollTo(0,0);
      }}]});
    }
  });
}

/* ===== v345: Group info page — a full dark page like Telegram's:
   round photo, name, member count, Message / Mute / Leave, the description card, a tab bar (Members · Media · Voice · Files · Links)
   and the members list in one rounded card (me first, «مدیر» badge in purple). It opens when the group name at the top of the chat is tapped.
   Owner tools (rename, photo, add / remove people) stay in the old sheet, reached from the ⋮ menu («ویرایش گروه»). ===== */
var GPG_I={
  back:'<svg viewBox="0 0 24 24" class="ic" aria-hidden="true"><path d="M20 12H4.5M10.5 5.5 4 12l6.5 6.5" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>',
  dots:'<svg viewBox="0 0 24 24" class="ic" aria-hidden="true"><circle cx="12" cy="5" r="2" fill="currentColor"/><circle cx="12" cy="12" r="2" fill="currentColor"/><circle cx="12" cy="19" r="2" fill="currentColor"/></svg>',
  msg:'<svg viewBox="0 0 24 24" class="ic" aria-hidden="true"><path fill="currentColor" d="M12 2.8c-5.5 0-9.6 3.600-9.600 8.300 0 2.400 1.100 4.500 2.900 6-.2 1.400-.9 2.700-2 3.600a.5.5 0 0 0 .4.9c2.100-.1 3.900-.8 5.200-1.900 1 .3 2 .4 3.100.4 5.500 0 9.600-3.600 9.600-8.300S17.500 2.800 12 2.800z"/></svg>',
  bell:'<svg viewBox="0 0 24 24" class="ic" aria-hidden="true"><path fill="currentColor" d="M12 2.500a6.500 6.500 0 0 0-6.500 6.500v3.700L3.800 16a1 1 0 0 0 .9 1.500h14.600a1 1 0 0 0 .9-1.500l-1.700-3.300V9A6.500 6.500 0 0 0 12 2.500zM9.500 19.200a2.500 2.500 0 0 0 5 0z"/></svg>',
  bellOff:'<svg viewBox="0 0 24 24" class="ic" aria-hidden="true"><path fill="currentColor" d="M12 2.500a6.500 6.500 0 0 0-6.500 6.500v3.700L3.800 16a1 1 0 0 0 .9 1.500h14.600a1 1 0 0 0 .9-1.500l-1.700-3.300V9A6.500 6.500 0 0 0 12 2.500zM9.500 19.200a2.500 2.500 0 0 0 5 0z" opacity=".55"/><path d="M4 4l16 16" stroke="currentColor" stroke-width="2.200" stroke-linecap="round" fill="none"/></svg>',
  leave:'<svg viewBox="0 0 24 24" class="ic" aria-hidden="true"><path d="M10.500 4H7a3 3 0 0 0-3 3v10a3 3 0 0 0 3 3h3.500M15 8l4 4-4 4M19 12H9.500" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>'
};
/* ===== v350: group admins + Telegram-style «Edit group» page.
   The owner («مدیر») and the admins the owner picks can change the name / photo / description and add members; admins can remove ordinary members;
   only the owner makes or removes admins (supabase/setup.sql, v350 block). ===== */
GPG_I.pen='<svg viewBox="0 0 24 24" class="ic" aria-hidden="true"><path d="M4 20h4L19 9a2.100 2.100 0 0 0-3-3L5 17zM14.500 7.500l3 3" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';
GPG_I.check='<svg viewBox="0 0 24 24" class="ic" aria-hidden="true"><path d="M5 12.500l4.500 4.500L19 7.500" fill="none" stroke="currentColor" stroke-width="2.300" stroke-linecap="round" stroke-linejoin="round"/></svg>';
GPG_I.cam='<svg viewBox="0 0 24 24" class="ic" aria-hidden="true"><path d="M4 8.500A2.500 2.500 0 0 1 6.500 6h1.600l1.200-1.800h4.400L15.900 6h1.600A2.500 2.500 0 0 1 20 8.500V16a2.500 2.500 0 0 1-2.500 2.500h-11A2.500 2.500 0 0 1 4 16z" fill="none" stroke="currentColor" stroke-width="1.800" stroke-linejoin="round"/><circle cx="12" cy="12" r="3.200" fill="none" stroke="currentColor" stroke-width="1.800"/></svg>';
GPG_I.shield='<svg viewBox="0 0 24 24" class="ic" aria-hidden="true"><path d="M12 3l7 2.800v5.600c0 4.300-2.900 7.800-7 9.600-4.100-1.800-7-5.300-7-9.600V5.800z" fill="none" stroke="currentColor" stroke-width="1.800" stroke-linejoin="round"/><path d="M12 8.800l1.100 2.300 2.500.3-1.800 1.700.5 2.500-2.300-1.200-2.300 1.200.5-2.500-1.800-1.700 2.500-.3z" fill="currentColor"/></svg>';
GPG_I.users='<svg viewBox="0 0 24 24" class="ic" aria-hidden="true"><circle cx="9" cy="8.500" r="3.200" fill="none" stroke="currentColor" stroke-width="1.800"/><path d="M3 19c.4-3.200 2.900-5 6-5s5.600 1.800 6 5" fill="none" stroke="currentColor" stroke-width="1.800" stroke-linecap="round"/><path d="M15.500 5.600a3 3 0 0 1 0 5.800M17.500 14.300c1.800.6 3.100 2 3.500 4.700" fill="none" stroke="currentColor" stroke-width="1.800" stroke-linecap="round"/></svg>';
GPG_I.addu='<svg viewBox="0 0 24 24" class="ic" aria-hidden="true"><circle cx="10" cy="8.500" r="3.400" fill="none" stroke="currentColor" stroke-width="1.800"/><path d="M3.500 19.500c.5-3.400 3.200-5.300 6.500-5.300 1.300 0 2.500.3 3.500.9" fill="none" stroke="currentColor" stroke-width="1.800" stroke-linecap="round"/><path d="M18.500 13v6M15.500 16h6" fill="none" stroke="currentColor" stroke-width="1.800" stroke-linecap="round"/></svg>';
function grIsAdm(g,uid){var m=grMember(g,uid);return !!(m&&m.is_admin)}
/* can I change this group's name / photo / description and add people? (owner or an admin) */
function grCan(g){return !!g&&(mcCns(g)||grIsAdm(g,CNX.uid))}
function grBadge(g,m){return m.user_id===g.counselor_id?'<em>'+__('مدیر','Owner')+'</em>':m.is_admin?'<em class="adm">'+__('ادمین','Admin')+'</em>':''}
function grAfter(done){return cnxLoad().then(function(){mcCardPaint();if(ui.tab==='kcm')render('swap');if(window.gpgRefresh)window.gpgRefresh();if(window.gpeRefresh)window.gpeRefresh();if(done)done()})}

/* add members (owner / admins) */
function grAddSheet(g,done){
  var id=g.id;
  var have=(g.members||[]).map(function(x){return x.user_id}),cand=grFriends().filter(function(f){return have.indexOf(f.id)<0});
  if(!cand.length){toast(__('همه‌ی دوستانت در گروه هستند.','All your friends are already in the group.'),null,null,'info');return}
  if(document.querySelector('.gr-wrap'))return;
  var s2=grSheet(__('افزودن عضو','Add member'),'<div class="gr-list">'+grPickHTML(cand,[])+'</div>',__('افزودن','Add'));
  s2.w.addEventListener('click',async function(ev){
    var c=ev.target.closest('[data-gr]');if(!c)return;
    if(c.dataset.gr==='close'){s2.close();return}
    if(c.dataset.gr!=='ok')return;
    var ids=grChecked(s2.w);if(!ids.length){s2.msg(grErrText({err:'members'}),1);return}
    c.disabled=true;var bad=null,i,r;
    for(i=0;i<ids.length;i++){r=await cnxReq('/rest/v1/rpc/group_add','POST',{p_group:id,p_user:ids[i]});if(!r.ok||!(r.j&&r.j.ok)){bad=r;break}}
    c.disabled=false;
    if(bad){s2.msg(grNoTable(bad)||(bad.ok?grErrText(bad.j):cnxNetErr(bad)),1);return}
    s2.close();await grAfter(done);
  });
}

/* group photo: gallery, one of the built-in avatars, or remove */
function grPhotoSheet(g,done){
  var id=g.id;
  if(document.querySelector('.gr-pick'))return;
  var s3=grSheet(__('عکس گروه','Group photo'),'<div class="gr-ph2"><button type="button" class="tt-btn" data-gr="gal">'+icon('camera')+__('انتخاب از گالری','Choose from gallery')+'</button>'+(grPhoto(g)?'<button type="button" class="tt-btn bad" data-gr="nophoto">'+__('حذف عکس','Remove photo')+'</button>':'')+'</div><div class="avgrid" id="grAvs">'+Object.keys(AVN).filter(function(a){return !isVip(a)}).map(function(a){return '<button type="button" class="avo" data-av="'+a+'" aria-pressed="'+(grPhoto(g)===a)+'" aria-label="'+AVN[a]+'"><span class="aimg '+a+'"></span></button>'}).join('')+'</div>','');
  s3.w.classList.add('gr-pick');
  async function setP(ph){
    var r=await cnxReq('/rest/v1/rpc/group_set_photo','POST',{p_group:id,p_photo:ph});
    if(!r.ok&&r.st===404){s3.msg(__('عکس گروه هنوز در Supabase ساخته نشده (بخش v304 فایل supabase/setup.sql را اجرا کن).','Group photos are not in Supabase yet (run the v304 block of supabase/setup.sql).'),1);return false}
    if(!r.ok){s3.msg(cnxNetErr(r),1);return false}
    if(!(r.j&&r.j.ok)){s3.msg(grErrText(r.j||{}),1);return false}
    await grAfter(done);return true;
  }
  s3.w.addEventListener('click',async function(ev){
    var c=ev.target.closest('[data-gr]');
    if(c){
      var k=c.dataset.gr;
      if(k==='close'){s3.close();return}
      if(k==='nophoto'){if(await setP(''))s3.close();return}
      if(k==='gal'){var gd=await grPickImage();if(!gd){s3.msg(__('عکس انتخاب نشد.','No photo was picked.'),1);return}s3.msg(__('در حال ذخیره…','Saving…'));if(await setP(gd))s3.close();return}
    }
    var a=ev.target.closest('[data-av]');if(!a)return;
    a.disabled=true;var ok=await setP(a.dataset.av);a.disabled=false;
    if(ok)s3.close();
  });
}

/* the people in the group; the owner removes anyone, an admin removes ordinary members */
function grMemSheet(g0,done){
  var id=g0.id;
  if(document.querySelector('.gr-wrap'))return;
  var sw=grSheet(__('اعضا','Members'),'<div class="gr-mems"></div>','');
  var box=sw.w.querySelector('.gr-mems');
  function canRm(g,m){return grCan(g)&&m.user_id!==CNX.uid&&m.user_id!==g.counselor_id&&(mcCns(g)||!m.is_admin)}
  function paint(){
    var g=mcLink(id);if(!g){sw.close();return}
    box.innerHTML=(g.members||[]).map(function(m){
      var me=m.user_id===CNX.uid,nm=m.name||__('عضو','Member');
      return '<div class="gr-mr">'+grMemAvHTML(g,m)+'<span dir="auto">'+esc(nm)+(me?' ('+__('تو','you')+')':'')+'</span>'+grBadge(g,m)+(canRm(g,m)?'<button type="button" class="mc-x" data-gr="rm" data-u="'+esc(m.user_id)+'" aria-label="'+__('حذف از گروه','Remove')+'">'+icon('close')+'</button>':'')+'</div>';
    }).join('');
  }
  paint();
  sw.w.addEventListener('click',function(e){
    var b=e.target.closest('[data-gr]');if(!b)return;
    if(b.dataset.gr==='close'){sw.close();return}
    if(b.dataset.gr!=='rm')return;
    var g=mcLink(id),mm=grMember(g,b.dataset.u);
    askConfirm({title:__('حذف از گروه؟','Remove from the group?'),msg:(mm&&mm.name||'')+' '+__('دیگر پیام‌های گروه را نمی‌بیند.','will no longer see the group’s messages.'),btns:[{t:__('حذف','Remove'),cls:'bad',fn:async function(){
      var r=await cnxReq('/rest/v1/rpc/group_remove','POST',{p_group:id,p_user:b.dataset.u});
      if(!r.ok||!(r.j&&r.j.ok)){sw.msg(grNoTable(r)||(r.ok?grErrText(r.j):cnxNetErr(r)),1);return}
      await grAfter(done);paint();
    }}]});
  });
}

/* admins: everybody can see the list; only the owner picks them */
function grAdmSheet(g0,done){
  var id=g0.id;
  if(document.querySelector('.gr-wrap'))return;
  var sw=grSheet(__('ادمین‌ها','Administrators'),'<p class="hint2">'+__('ادمین‌ها می‌توانند نام، عکس و توضیحات گروه را عوض کنند و عضو اضافه کنند. فقط مدیر گروه ادمین انتخاب می‌کند.','Admins can change the group’s name, photo and description and add members. Only the owner picks admins.')+'</p><div class="gr-mems"></div>','');
  var box=sw.w.querySelector('.gr-mems');
  function paint(){
    var g=mcLink(id);if(!g){sw.close();return}
    var own=mcCns(g);
    box.innerHTML=(g.members||[]).filter(function(m){return own||m.user_id===g.counselor_id||m.is_admin}).map(function(m){
      var me=m.user_id===CNX.uid,nm=m.name||__('عضو','Member'),isO=m.user_id===g.counselor_id;
      return '<div class="gr-mr">'+grMemAvHTML(g,m)+'<span dir="auto">'+esc(nm)+(me?' ('+__('تو','you')+')':'')+'</span>'+grBadge(g,m)+(own&&!isO?'<button type="button" class="tt-btn'+(m.is_admin?' bad':'')+'" data-gr="adm" data-u="'+esc(m.user_id)+'" data-on="'+(m.is_admin?'0':'1')+'">'+(m.is_admin?__('حذف از ادمین','Remove admin'):__('ادمین کن','Make admin'))+'</button>':'')+'</div>';
    }).join('');
  }
  paint();
  sw.w.addEventListener('click',async function(e){
    var b=e.target.closest('[data-gr]');if(!b)return;
    if(b.dataset.gr==='close'){sw.close();return}
    if(b.dataset.gr!=='adm')return;
    b.disabled=true;
    var r=await cnxReq('/rest/v1/rpc/group_set_admin','POST',{p_group:id,p_user:b.dataset.u,p_on:b.dataset.on==='1'});
    if(!r.ok&&r.st===404){b.disabled=false;sw.msg(__('ادمین گروه هنوز در Supabase ساخته نشده (بخش v350 فایل supabase/setup.sql را اجرا کن).','Group admins are not in Supabase yet (run the v350 block of supabase/setup.sql).'),1);return}
    if(!r.ok||!(r.j&&r.j.ok)){b.disabled=false;sw.msg(r.ok?grErrText(r.j):cnxNetErr(r),1);return}
    await grAfter(done);paint();sw.msg('');
  });
}

/* Telegram-style «Edit» page: photo + name + description, then Administrators / Members / Add member. The ✓ saves the name and description. */
function gpeKill(){var o=document.querySelector('.gpe');if(o)o.remove();ui.gpe=false;window.gpeRefresh=null}
function grEditPage(l){
  if(document.querySelector('.gpe'))return;
  var id=l.id,g0=mcLink(id);
  if(!g0||!grCan(g0))return;
  var o=document.createElement('div');o.className='gpe';o.setAttribute('role','dialog');o.setAttribute('aria-modal','true');o.setAttribute('aria-label',__('ویرایش گروه','Edit group'));
  o.innerHTML='<div class="gpe-top"><button type="button" data-e="back" aria-label="'+__('برگشت','Back')+'">'+GPG_I.back+'</button><h2>'+__('ویرایش','Edit')+'</h2><button type="button" class="gpe-ok" data-e="ok" aria-label="'+__('ذخیره','Save')+'">'+GPG_I.check+'</button></div><div class="gpe-body"></div>';
  document.body.appendChild(o);
  var BD=o.querySelector('.gpe-body'),draft={n:null,d:null},busy=0;
  function G(){return mcLink(id)}
  function keep(){var a=BD.querySelector('#gpeNm'),b=BD.querySelector('#gpeDs');if(a)draft.n=a.value;if(b)draft.d=b.value}
  function paint(){
    var g=G();if(!g||!grCan(g)){gpeKill();return}
    keep();
    var own=mcCns(g),nmV=draft.n!=null?draft.n:g.name,dV=draft.d!=null?draft.d:(g.description||''),ms=g.members||[];
    var adm=ms.filter(function(m){return m.is_admin&&m.user_id!==g.counselor_id}).length+1;
    BD.innerHTML='<div class="gpe-cd"><div class="gpe-nm"><button type="button" class="gpe-pic" data-e="photo" aria-label="'+__('عکس گروه','Group photo')+'"><i class="gr-av'+(grPhoto(g)?' has-p':'')+'" style="--h:'+grHue(g.name)+'">'+grAvIn(g)+'</i></button><input class="gpe-in" id="gpeNm" maxlength="60" dir="auto" autocomplete="off" placeholder="'+__('نام گروه','Group name')+'" value="'+esc(nmV)+'"></div>'+
      '<button type="button" class="gpe-row blue" data-e="photo">'+GPG_I.cam+'<span>'+__('انتخاب عکس','Set photo')+'</span></button>'+
      '<textarea class="gpe-ds" id="gpeDs" rows="2" maxlength="255" dir="auto" placeholder="'+__('توضیحات (اختیاری)','Description (optional)')+'">'+esc(dV)+'</textarea></div>'+
      '<div class="gpe-cd"><button type="button" class="gpe-row" data-e="adm">'+GPG_I.shield+'<span>'+__('ادمین‌ها','Administrators')+'</span><em>'+fa(adm)+'</em></button><button type="button" class="gpe-row" data-e="mem">'+GPG_I.users+'<span>'+__('اعضا','Members')+'</span><em>'+fa(ms.length)+'</em></button></div>'+
      '<p class="gpe-hint">'+(own?__('ادمین‌ها را فقط تو، مدیر گروه، انتخاب می‌کنی.','Only you, the owner, can pick the admins.'):__('فقط مدیر گروه ادمین انتخاب می‌کند.','Only the owner picks the admins.'))+'</p>'+
      '<div class="gpe-cd"><button type="button" class="gpe-row blue" data-e="add">'+GPG_I.addu+'<span>'+__('افزودن عضو','Add member')+'</span></button></div>';
  }
  window.gpeRefresh=paint;
  paint();
  subPush();ui.gpe=true;
  function closeThen(){if(history.state&&history.state.sub)history.back();else gpeKill()}
  async function save(){
    var g=G();if(!g||busy)return;
    keep();
    var nm=String(draft.n!=null?draft.n:g.name).trim(),ds=String(draft.d!=null?draft.d:(g.description||'')).trim();
    if(!nm){toast(grErrText({err:'name'}),null,null,'warn');return}
    busy=1;var ok=true,r;
    if(nm!==g.name){
      r=await cnxReq('/rest/v1/rpc/group_rename','POST',{p_group:id,p_name:nm});
      if(!r.ok||!(r.j&&r.j.ok)){ok=false;toast(grNoTable(r)||(r.ok?grErrText(r.j):cnxNetErr(r)),null,null,'warn')}
    }
    if(ok&&ds!==String(g.description||'').trim()){
      r=await cnxReq('/rest/v1/rpc/group_set_desc','POST',{p_group:id,p_desc:ds});
      if(!r.ok){ok=false;toast(r.st===404?__('توضیحات گروه هنوز در Supabase ساخته نشده (بخش v345 فایل supabase/setup.sql را اجرا کن).','Group descriptions are not in Supabase yet (run the v345 block of supabase/setup.sql).'):cnxNetErr(r),null,null,'warn')}
      else if(!(r.j&&r.j.ok)){ok=false;toast(grErrText(r.j||{}),null,null,'warn')}
    }
    busy=0;
    if(!ok)return;
    draft.n=draft.d=null;
    await grAfter();
    hap('send');toast(__('تغییرات ذخیره شد','Changes saved'),null,null,'ok');
    closeThen();
  }
  o.addEventListener('click',function(e){
    var b=e.target.closest('[data-e]');if(!b)return;
    var k=b.dataset.e,g=G();if(!g){closeThen();return}
    if(k==='back'){closeThen();return}
    if(k==='ok'){save();return}
    keep();
    if(k==='photo'){grPhotoSheet(g,paint);return}
    if(k==='adm'){grAdmSheet(g,paint);return}
    if(k==='mem'){grMemSheet(g,paint);return}
    if(k==='add'){grAddSheet(g,paint);return}
  });
}

function gpgKill(){var o=document.querySelector('.gpg');if(o)o.remove();ui.gpg=false;window.gpgRefresh=null}
function gpgLastMsg(gid,uid){var a=MC.msgs[gid]||[],i;for(i=a.length-1;i>=0;i--)if(a[i].sender_id===uid&&!a[i].pending&&!a[i].failed)return a[i];return null}
function gpgStatus(g,m){
  if(m.user_id===CNX.uid)return {t:__('آنلاین','online'),on:1};
  var lm=gpgLastMsg(g.id,m.user_id);
  if(lm)return {t:__('آخرین پیام: ','Last message: ')+kcxDay(mcMs(lm.created_at))+' '+kcxTime(mcMs(lm.created_at))};
  if(m.joined_at)return {t:__('پیوسته در ','Joined ')+cnxDate(m.joined_at)};
  return {t:__('عضو گروه','Group member')};
}
function grpPage(l){
  if(document.querySelector('.gpg'))return;
  var id=l.id,cur='u',menuOn=false;
  var o=document.createElement('div');o.className='gpg';o.setAttribute('role','dialog');o.setAttribute('aria-modal','true');o.setAttribute('aria-label',l.name||'');
  o.innerHTML='<div class="gpg-top"><button type="button" data-g="back" aria-label="'+__('برگشت','Back')+'">'+GPG_I.back+'</button><span class="gpg-tr"><button type="button" class="gpg-pen" data-g="edit" hidden aria-label="'+__('ویرایش گروه','Edit group')+'">'+GPG_I.pen+'</button><button type="button" data-g="menu" aria-label="'+__('بیشتر','More')+'">'+GPG_I.dots+'</button></span></div><div class="gpg-menu" hidden></div>'+
    '<div class="gpg-hd"></div><div class="gpg-acts"></div><div class="gpg-dc"></div><div class="gpg-tabs" role="tablist"></div><div class="gpg-body"></div>';
  document.body.appendChild(o);
  var HD=o.querySelector('.gpg-hd'),AC=o.querySelector('.gpg-acts'),DC=o.querySelector('.gpg-dc'),TB=o.querySelector('.gpg-tabs'),BD=o.querySelector('.gpg-body'),MN=o.querySelector('.gpg-menu');
  function G(){return mcLink(id)}
  function nameOf(g,uid){var m=grMember(g,uid);return (m&&m.name)||__('عضو','Member')}
  function paintHead(g){
    var own=grCan(g),ms=g.members||[];
    o.querySelector('.gpg-pen').hidden=!own;
    HD.innerHTML='<button type="button" class="gpg-pic" data-g="pic"'+(own?'':' tabindex="-1"')+' aria-label="'+esc(g.name)+'"><i class="gr-av big'+(grPhoto(g)?' has-p':'')+'" style="--h:'+grHue(g.name)+'">'+grAvIn(g)+'</i></button><h2 class="gpg-nm" dir="auto">'+esc(g.name)+'</h2><p class="gpg-ct">'+fa(ms.length)+' '+__('عضو','members')+'</p>';
    var mu=mcMuted(id);
    AC.innerHTML='<button type="button" data-g="msg">'+GPG_I.msg+'<span>'+__('پیام','Message')+'</span></button><button type="button" data-g="mute">'+(mu?GPG_I.bellOff:GPG_I.bell)+'<span>'+(mu?__('باز کردن صدا','Unmute'):__('بی‌صدا','Mute'))+'</span></button><button type="button" data-g="leave">'+GPG_I.leave+'<span>'+__('ترک','Leave')+'</span></button>';
    var d=String(g.description||'').trim();
    if(d||own)DC.innerHTML='<'+(own?'button type="button" data-g="desc"':'div')+' class="gpg-d'+(d?'':' empty')+'"><b dir="auto">'+esc(d||__('افزودن توضیحات','Add a description'))+'</b><small>'+__('توضیحات','Description')+'</small></'+(own?'button':'div')+'>';
    else DC.innerHTML='';
    var own2=own;
    MN.innerHTML=(own2?'<button type="button" data-g="edit" dir="auto">'+__('ویرایش گروه','Edit group')+'</button><button type="button" data-g="add" dir="auto">'+__('افزودن عضو','Add member')+'</button>':'')+'<button type="button" data-g="leave" class="bad" dir="auto">'+__('ترک گروه','Leave group')+'</button>';
  }
  function tabs(){return [['u',__('اعضا','Members')],['m',__('رسانه','Media')],['a',__('صدا','Voice')],['f',__('فایل‌ها','Files')],['l',__('لینک‌ها','Links')]]}
  function paintTabs(){TB.innerHTML=tabs().map(function(t){return '<button type="button" role="tab" aria-selected="'+(t[0]===cur)+'" data-gt="'+t[0]+'">'+t[1]+'</button>'}).join('')}
  function items(k){
    var A=(MC.msgs[id]||[]).filter(function(m){return !m.pending&&!m.failed});
    if(k==='m')return A.filter(function(m){return m.kind==='p'||m.kind==='v'||m.kind==='r'});
    if(k==='f')return A.filter(function(m){return m.kind==='f'});
    if(k==='a')return A.filter(function(m){return m.kind==='a'});
    var out=[];A.forEach(function(m){if(m.kind==='t')mcpUrls(m.body).forEach(function(u){out.push({id:m.id,url:u,created_at:m.created_at,sender_id:m.sender_id})})});return out;
  }
  function paintBody(g){
    var h='';
    if(cur==='u'){
      var ms=(g.members||[]).slice().sort(function(a,b){return (b.user_id===CNX.uid)-(a.user_id===CNX.uid)});
      h='<div class="gpg-cd">'+(grCan(g)?'<button type="button" class="gpg-mr gpg-add" data-g="addm"><span class="gpg-ai">'+GPG_I.addu+'</span><span class="gpg-mt"><b dir="auto">'+__('افزودن عضو','Add Members')+'</b></span></button>':'')+ms.map(function(m){
        var st=gpgStatus(g,m),nm=m.name||__('عضو','Member');
        return '<button type="button" class="gpg-mr" data-g="mp" data-u="'+esc(m.user_id)+'">'+grMemAvHTML(g,m)+'<span class="gpg-mt"><b dir="auto">'+esc(nm)+'</b><small dir="auto"'+(st.on?' class="on"':'')+'>'+esc(st.t)+'</small></span>'+grBadge(g,m)+'</button>';
      }).join('')+'</div>';
      BD.innerHTML=h;return;
    }
    var it=items(cur).slice().reverse();
    if(!it.length){BD.innerHTML='<p class="gpg-e">'+__('هنوز چیزی در این بخش نیست.','Nothing here yet.')+'</p>';return}
    if(cur==='m'){
      h='<div class="mcp-grid gpg-grid">'+it.map(function(m){return '<button type="button" class="mcp-g" data-mcpm="'+esc(m.id)+'" aria-label="'+(m.kind==='p'?__('عکس','Photo'):__('ویدیو','Video'))+'"><img alt="" data-mcpi="'+esc(m.id)+'" draggable="false">'+(m.kind!=='p'?'<span class="sp-pl">'+SP_PLAY+'</span>':'')+'</button>'}).join('')+'</div>';
    }else if(cur==='f'){
      h='<div class="gpg-cd">'+it.map(function(m){return '<button type="button" class="gpg-r" data-mcf="'+esc(m.id)+'"><span class="mc-fi"><svg viewBox="0 0 24 24" class="ic" aria-hidden="true"><path d="M7 3.5h8l4 4V20a.5.5 0 0 1-.5.5h-11A.5.5 0 0 1 7 20z"/><path d="M14.5 3.5V8H19"/></svg></span><span class="mc-ft"><b dir="auto">'+esc(m.mname||__('فایل','File'))+'</b><small dir="auto">'+esc(nameOf(g,m.sender_id))+' · '+mcSize(m.msize)+' · '+kcxDay(mcMs(m.created_at))+'</small></span></button>'}).join('')+'</div>';
    }else if(cur==='a'){
      h='<div class="gpg-cd">'+it.map(function(m){var d=Math.round(+(m.meta&&m.meta.d)||0);return '<button type="button" class="gpg-r" data-mcpj="'+esc(m.id)+'"><span class="mc-fi">🎤</span><span class="mc-ft"><b dir="auto">'+(m.sender_id===CNX.uid?__('تو','You'):esc(nameOf(g,m.sender_id)))+'</b><small>'+(d?fa(Math.floor(d/60))+':'+fa(('0'+d%60).slice(-2))+' · ':'')+kcxDay(mcMs(m.created_at))+' '+kcxTime(mcMs(m.created_at))+'</small></span></button>'}).join('')+'</div>';
    }else{
      h='<div class="gpg-cd">'+it.map(function(x){return '<button type="button" class="gpg-r" data-mcpj="'+esc(x.id)+'"><span class="mc-fi">🔗</span><span class="mc-ft"><b dir="ltr" style="text-align:start">'+esc(x.url.replace(/^https?:\/\//,'').slice(0,60))+'</b><small dir="auto">'+esc(nameOf(g,x.sender_id))+' · '+kcxDay(mcMs(x.created_at))+'</small></span></button>'}).join('')+'</div>';
    }
    BD.innerHTML=h;
    if(cur==='m')it.forEach(function(m){
      var im=BD.querySelector('img[data-mcpi="'+m.id+'"]');if(!im)return;
      var pth=m.thumb||(m.kind==='p'?m.media:'');
      if(SP.mem['spt_'+m.id]){im.src=SP.mem['spt_'+m.id];return}
      if(VN.mem['vnp_'+m.id]){im.src=VN.mem['vnp_'+m.id];return}
      if(pth)mcBlob(pth).then(function(x){im.src=x.u}).catch(function(){});
    });
  }
  function refresh(){var g=G();if(!g){gpgKill();return}paintHead(g);paintTabs();paintBody(g)}
  window.gpgRefresh=refresh;
  refresh();
  subPush();ui.gpg=true;
  function closeThen(fn,wait){if(history.state&&history.state.sub){history.back();if(fn)setTimeout(fn,wait||350)}else{gpgKill();if(fn)fn()}}
  function menuSet(on){menuOn=on;MN.hidden=!on}
  function leaveAsk(){
    askConfirm({title:__('ترک گروه؟','Leave the group?'),msg:__('دیگر پیام‌های این گروه را نمی‌بینی.','You will no longer see this group’s messages.'),btns:[{t:__('ترک گروه','Leave'),cls:'bad',fn:async function(){
      var r=await cnxReq('/rest/v1/rpc/group_leave','POST',{p_group:id});
      if(!r.ok||!(r.j&&r.j.ok)){toast(grNoTable(r)||(r.ok?grErrText(r.j):cnxNetErr(r)),null,null,'warn');return}
      delete MC.msgs[id];delete MC.sum[id];delete MC.un[id];delete MC.last[id];
      await cnxLoad();
      closeThen(function(){mcStop();ui.mcl='#f';ui.mcFrom='';render('enter');window.scrollTo(0,0)},150);
    }}]});
  }
  function descEdit(){
    var g=G();if(!g||!grCan(g)||document.querySelector('.gr-wrap'))return;
    var sw=grSheet(__('توضیحات گروه','Group description'),'<textarea class="field" id="grDesc" rows="4" maxlength="255" dir="auto" placeholder="'+__('درباره‌ی این گروه بنویس…','Write about this group…')+'"></textarea>',__('ذخیره','Save'));
    var ta=sw.w.querySelector('#grDesc');ta.value=String(g.description||'');
    sw.w.addEventListener('click',async function(e){
      var b=e.target.closest('[data-gr]');if(!b)return;
      if(b.dataset.gr==='close'){sw.close();return}
      if(b.dataset.gr!=='ok')return;
      b.disabled=true;
      var r=await cnxReq('/rest/v1/rpc/group_set_desc','POST',{p_group:id,p_desc:ta.value.trim()});
      b.disabled=false;
      if(!r.ok){sw.msg(r.st===404?__('توضیحات گروه هنوز در Supabase ساخته نشده (بخش v345 فایل supabase/setup.sql را اجرا کن).','Group descriptions are not in Supabase yet (run the v345 block of supabase/setup.sql).'):cnxNetErr(r),1);return}
      if(!(r.j&&r.j.ok)){sw.msg(grErrText(r.j||{}),1);return}
      await cnxLoad();sw.close();refresh();
    });
  }
  o.addEventListener('click',function(e){
    var b;
    if(menuOn&&!e.target.closest('.gpg-menu')&&!e.target.closest('[data-g="menu"]'))menuSet(false);
    if((b=e.target.closest('[data-gt]'))){cur=b.dataset.gt;paintTabs();var g0=G();if(g0)paintBody(g0);return}
    if((b=e.target.closest('[data-mcpm]'))){mcShowMedia(b.dataset.mcpm);return}
    if((b=e.target.closest('[data-mcf]'))){mcSaveMsg(b.dataset.mcf);return}
    if((b=e.target.closest('[data-mcpj]'))){
      var jid=b.dataset.mcpj;
      closeThen(function(){var r=document.querySelector('.kcx-row[data-mid="'+jid+'"]');if(r){r.scrollIntoView({block:'center',behavior:'smooth'});r.classList.remove('mc-flash');void r.offsetWidth;r.classList.add('mc-flash')}},380);
      return;
    }
    if(!(b=e.target.closest('[data-g]')))return;
    var k=b.dataset.g,g=G();if(!g&&k!=='back')return;
    if(k==='back'){closeThen();return}
    if(k==='menu'){menuSet(!menuOn);return}
    if(k==='msg'){closeThen(function(){var t=document.getElementById('mcT');if(t)t.focus()});return}
    if(k==='mute'){var on=!mcMuted(id);mcMuteSet(id,on);paintHead(g);toast(on?__('اعلان‌های این گروه بی‌صدا شد','Notifications of this group are muted'):__('اعلان‌ها دوباره روشن شد','Notifications are back on'),null,null,'info');return}
    if(k==='leave'){menuSet(false);leaveAsk();return}
    if(k==='desc'){descEdit();return}
    if(k==='pic'){if(grCan(g))grPhotoSheet(g,refresh);return}
    if(k==='edit'){menuSet(false);grEditPage(g);return}
    if(k==='add'||k==='addm'){menuSet(false);grAddSheet(g,refresh);return}
    if(k==='mp'){var pm=grMember(g,b.dataset.u);mcpOpen(g,{uid:b.dataset.u,name:pm&&pm.name});return}
  });
}

/* ----- opening / closing ----- */
/* ----- chat scroll: open exactly where I left (or at the newest message), with NO sliding from the top ----- */
MC.sp={};MC.spHold=0;MC.spT=0;
function mcJump(L,top){var b=L.style.scrollBehavior;L.style.scrollBehavior='auto';L.scrollTop=top;L.style.scrollBehavior=b}   /* the thread has scroll-behavior:smooth in CSS, which made a plain scrollTop slide from the first message down to the last */
function mcSpApply(id){
  var L=document.getElementById('mcL');if(!L)return;
  var v=MC.sp[id];mcJump(L,v&&!v.e?v.t:L.scrollHeight);
}
/* places the thread, then keeps it there for a moment while pictures / bubbles finish growing (stops as soon as I touch it) */
function mcSpHold(id){
  MC.spHold=1;mcSpApply(id);
  [60,180,420,800].forEach(function(t){setTimeout(function(){if(MC.spHold&&ui.mcl===id)mcSpApply(id)},t)});
  clearTimeout(MC.spT);MC.spT=setTimeout(function(){MC.spHold=0},900);
}
function mcSpSave(id){var L=document.getElementById('mcL');if(!L||MC.spHold)return;MC.sp[id]={t:L.scrollTop,e:L.scrollHeight-L.scrollTop-L.clientHeight<80}}
function mcOpenChat(id,from){
  if(ui.tab!=='kcm')ui.mcTab=ui.tab;
  subPush();ui.tab='kcm';ui.kcsec='';ui.mcl=id;ui.mcFrom=from===true?'*':from||'';render('enter');window.scrollTo(0,0);
}
actions.mcCard=function(){
  var ls=mcLinks();if(!ls.length){mcRefresh(true);return}
  if(ls.length===1){mcOpenChat(ls[0].id,'');return}
  if(ui.tab!=='kcm')ui.mcTab=ui.tab;
  subPush();ui.tab='kcm';ui.kcsec='';ui.mcl='*';ui.mcFrom='';render('enter');window.scrollTo(0,0);
};
actions.mcOpen=function(d){mcOpenChat(d.id,d.from||'*')};
function mcStop(){clearInterval(MC.poll);MC.poll=0;clearInterval(MC.prT);MC.prT=0;MC.typAt=0;mcpKill();if(typeof gpeKill==='function')gpeKill();if(typeof gpgKill==='function')gpgKill()}
/* ---------- v281: the other person's profile page (like Telegram's, without phone / call) ---------- */
function mcMutedMap(){try{return JSON.parse(localStorage.getItem('ario.mcmute')||'{}')||{}}catch(e){return {}}}
function mcMuted(id){return kcMuted('lk:'+id)}
function mcMuteSet(id,on){var m=mcMutedMap();if(on)m[id]=1;else delete m[id];try{localStorage.setItem('ario.mcmute',JSON.stringify(m))}catch(e){}if(!on){var D=kcD();if(D.mu&&D.mu['lk:'+id]){delete D.mu['lk:'+id];persist()}}}
/* "Clear chat" in a friend / group / advisor chat hides the messages for me only (a cut-off time kept on this phone) */
function mcClrMap(){try{return JSON.parse(localStorage.getItem('ario.mcclr')||'{}')||{}}catch(e){return {}}}
function mcClrAt(id){return +mcClrMap()[id]||0}
function mcClrSet(id,ts){var m=mcClrMap();if(ts)m[id]=ts;else delete m[id];try{localStorage.setItem('ario.mcclr',JSON.stringify(m))}catch(e){}}
function mcpKill(){var o=document.querySelector('.mcp');if(o)o.remove();ui.mcp=false}
function mcpClose(){mcpKill()}
function mcpUrls(t){return String(t||'').match(/https?:\/\/[^\s<>"']+/g)||[]}
/* v307: a group member's profile (tap the member's picture beside a message, or the member in Group info). mem = {uid,name} */
function grMember(g,uid){var ms=(g&&g.members)||[],i;for(i=0;i<ms.length;i++)if(ms[i].user_id===uid)return ms[i];return null}
function grMemAv(g,uid,name){
  if(uid===CNX.uid)return mcMyAv();
  var a=MC.msgs[g.id]||[],i,v,nm=String(name||'');
  for(i=a.length-1;i>=0;i--){if(a[i].sender_id===uid&&a[i].meta&&a[i].meta.av){v=a[i].meta.av;return {p:okPhoto(v.p)&&!isVip(v.p)?v.p:'',h:isFinite(+v.h)?+v.h:mcHue(nm),n:Array.from(String(v.n||nm))[0]||''}}}
  return {p:'',h:mcHue(nm),n:Array.from(nm)[0]||''};
}
function grMemAvHTML(g,m){var v=grMemAv(g,m.user_id,m.name||'');return '<i class="gr-av'+(v.p?' has-p':'')+'" style="--h:'+v.h+'">'+(v.p?'<span class="aimg '+v.p+'"></span>':esc(v.n||'ع'))+'</i>'}
function mcpOpen(l,mem){
  var gm=null;
  if(mcGr(l)){
    if(!mem){grpPage(l);return}
    var gmm=grMember(l,mem.uid);
    gm={uid:mem.uid,name:(gmm&&gmm.name)||mem.name||__('عضو','Member'),joined:gmm&&gmm.joined_at};
  }
  if(document.querySelector('.mcp'))return;
  var id=l.id,av=gm?grMemAv(l,gm.uid,gm.name):mcPeerAv(l),nm=gm?gm.name:mcPeer(l),fr=mcFr(l),cn=mcCns(l);
  var gmMe=gm&&gm.uid===CNX.uid,gmFr=gm&&!gmMe?mcFriends().filter(function(f){return (mcCns(f)?f.student_id:f.counselor_id)===gm.uid})[0]:null;
  var role=gm?(gm.uid===l.counselor_id?__('مدیر گروه','Group owner'):(gmm&&gmm.is_admin)?__('ادمین گروه','Group admin'):__('عضو گروه','Group member')):fr?__('دوست تو','Your friend'):cn?__('دانش‌آموز تو','Your student'):__('مشاور تو','Your advisor');
  var base=function(){var A=MC.msgs[id]||[];return gm?A.filter(function(m){return m.sender_id===gm.uid}):A};
  var a=base(),last=null,i;
  for(i=a.length-1;i>=0;i--)if(a[i].sender_id!==CNX.uid||gmMe){last=a[i];break}
  var st=last?__('آخرین پیام: ','Last message: ')+kcxDay(mcMs(last.created_at))+' '+kcxTime(mcMs(last.created_at)):__('هنوز پیامی نفرستاده','No message from them yet');
  var ph=av.p?'<span class="aimg '+av.p+'" role="img" aria-label="'+esc(nm)+'"></span>':'<b>'+esc(av.n)+'</b>';
  var o=document.createElement('div');o.className='mcp';o.setAttribute('role','dialog');o.setAttribute('aria-modal','true');o.setAttribute('aria-label',nm);
  o.innerHTML='<div class="mcp-hero" style="--h:'+av.h+'"><div class="mcp-ph">'+ph+'</div><div class="mcp-sh"></div>'+
    '<button type="button" class="mcp-back" data-mcp="close" aria-label="'+__('برگشت','Back')+'">'+icon('chev')+'</button>'+
    '<div class="mcp-melt"></div><div class="mcp-bot"><div class="mcp-id"><h2 dir="auto">'+esc(nm)+'</h2><p>'+esc(st)+'</p></div>'+
    (gm?(gmFr?'<div class="mcp-acts"><button type="button" data-mcp="gmsg">'+icon('chat')+'<span>'+__('پیام خصوصی','Private message')+'</span></button></div>':''):'<div class="mcp-acts"><button type="button" data-mcp="msg">'+icon('chat')+'<span>'+__('پیام','Message')+'</span></button><button type="button" data-mcp="mute" class="'+(mcMuted(id)?'on':'')+'">'+icon('bell')+'<span>'+(mcMuted(id)?__('بی‌صدا شده','Muted'):__('بی‌صدا','Mute'))+'</span></button></div>')+'</div></div>'+
    '<div class="mcp-card glass"><div><b>'+esc(role)+'</b><small>'+(gm?__('نقش در گروه «','Role in the group “')+esc(l.name||'')+(__('»','”')):__('نقش در این گفتگو','Role in this chat'))+'</small></div>'+(gm?(gm.joined?'<div><b>'+esc(cnxDate(gm.joined))+'</b><small>'+__('تاریخ پیوستن','Joined on')+'</small></div>':''):(l.linked_at?'<div><b>'+esc(cnxDate(l.linked_at))+'</b><small>'+__('تاریخ اتصال','Connected on')+'</small></div>':''))+'<div><b>'+fa(a.length)+'</b><small>'+(gm?__('پیام‌ها در این گروه','Messages in this group'):__('پیام‌های بارگیری‌شده','Messages loaded'))+'</small></div></div>'+
    '<div class="mcp-tabs" role="tablist"></div><div class="mcp-body"></div>';
  document.body.appendChild(o);
  var tabs=[['m',__('رسانه','Media')],['f',__('فایل‌ها','Files')],['a',__('صدا','Voice')],['l',__('لینک‌ها','Links')],['g',__('گزارش‌ها','Reports')]],cur='m',TB=o.querySelector('.mcp-tabs'),BD=o.querySelector('.mcp-body');
  function items(k){
    var A=base().filter(function(m){return !m.pending&&!m.failed});
    if(k==='m')return A.filter(function(m){return m.kind==='p'||m.kind==='v'||m.kind==='r'});
    if(k==='f')return A.filter(function(m){return m.kind==='f'});
    if(k==='a')return A.filter(function(m){return m.kind==='a'});
    if(k==='g')return A.filter(function(m){return m.kind==='g'});
    var out=[];A.forEach(function(m){if(m.kind==='t')mcpUrls(m.body).forEach(function(u){out.push({id:m.id,url:u,created_at:m.created_at})})});return out;
  }
  function paint(){
    TB.innerHTML=tabs.map(function(t){return '<button type="button" role="tab" aria-selected="'+(t[0]===cur)+'" data-mcpt="'+t[0]+'">'+t[1]+'</button>'}).join('');
    var it=items(cur).slice().reverse(),h='';
    if(!it.length){BD.innerHTML='<p class="mcp-e">'+__('هنوز چیزی در این بخش نیست.','Nothing here yet.')+'</p>';return}
    if(cur==='m'){
      h='<div class="mcp-grid">'+it.map(function(m){return '<button type="button" class="mcp-g" data-mcpm="'+esc(m.id)+'" aria-label="'+(m.kind==='p'?__('عکس','Photo'):__('ویدیو','Video'))+'"><img alt="" data-mcpi="'+esc(m.id)+'" draggable="false">'+(m.kind!=='p'?'<span class="sp-pl">'+SP_PLAY+'</span>':'')+'</button>'}).join('')+'</div>';
    }else if(cur==='f'){
      h=it.map(function(m){return '<button type="button" class="mcp-r" data-mcf="'+esc(m.id)+'"><span class="mc-fi"><svg viewBox="0 0 24 24" class="ic" aria-hidden="true"><path d="M7 3.5h8l4 4V20a.5.5 0 0 1-.5.5h-11A.5.5 0 0 1 7 20z"/><path d="M14.5 3.5V8H19"/></svg></span><span class="mc-ft"><b dir="auto">'+esc(m.mname||__('فایل','File'))+'</b><small>'+mcSize(m.msize)+' · '+kcxDay(mcMs(m.created_at))+'</small></span></button>'}).join('');
    }else if(cur==='a'){
      h=it.map(function(m){var d=Math.round(+(m.meta&&m.meta.d)||0);return '<button type="button" class="mcp-r" data-mcpj="'+esc(m.id)+'"><span class="mc-fi">🎤</span><span class="mc-ft"><b>'+(m.sender_id===CNX.uid?__('تو','You'):esc(nm))+'</b><small>'+(d?fa(Math.floor(d/60))+':'+fa(('0'+d%60).slice(-2))+' · ':'')+kcxDay(mcMs(m.created_at))+' '+kcxTime(mcMs(m.created_at))+'</small></span></button>'}).join('');
    }else if(cur==='g'){
      h=it.map(function(m){var me=m.meta||{},dl='';try{dl=F.long.format(parse(me.day))}catch(e){dl=me.day||''}return '<button type="button" class="mcp-r" data-mcpj="'+esc(m.id)+'"><span class="mc-fi">📝</span><span class="mc-ft"><b>'+esc(dl)+'</b><small>'+(m.sender_id===CNX.uid?__('تو','You'):esc(nm))+' · '+kcxTime(mcMs(m.created_at))+'</small></span></button>'}).join('');
    }else{
      h=it.map(function(x){return '<button type="button" class="mcp-r" data-mcpj="'+esc(x.id)+'"><span class="mc-fi">🔗</span><span class="mc-ft"><b dir="ltr" style="text-align:start">'+esc(x.url.replace(/^https?:\/\//,'').slice(0,60))+'</b><small>'+kcxDay(mcMs(x.created_at))+'</small></span></button>'}).join('');
    }
    BD.innerHTML=h;
    if(cur==='m')it.forEach(function(m){
      var im=BD.querySelector('img[data-mcpi="'+m.id+'"]');if(!im)return;
      var pth=m.thumb||(m.kind==='p'?m.media:'');
      if(SP.mem['spt_'+m.id]){im.src=SP.mem['spt_'+m.id];return}
      if(VN.mem['vnp_'+m.id]){im.src=VN.mem['vnp_'+m.id];return}
      if(pth)mcBlob(pth).then(function(x){im.src=x.u}).catch(function(){});
    });
  }
  paint();
  subPush();ui.mcp=true;
  o.addEventListener('click',function(e){
    var b;
    if((b=e.target.closest('[data-mcp]'))){
      var k=b.dataset.mcp;
      if(k==='close'){if(history.state&&history.state.sub)history.back();else mcpKill()}
      else if(k==='msg'){var foc=function(){var t=document.getElementById('mcT');if(t)t.focus()};if(history.state&&history.state.sub){history.back();setTimeout(foc,350)}else{mcpKill();foc()}}
      else if(k==='gmsg'&&gmFr){
        var fid=gmFr.id,go=function(){var sh=document.querySelector('.gr-info');if(sh)sh.remove();mcOpenChat(fid,id)};
        if(history.state&&history.state.sub){history.back();setTimeout(go,350)}else{mcpKill();go()}
      }
      else if(k==='mute'){var on=!mcMuted(id);mcMuteSet(id,on);b.classList.toggle('on',on);b.querySelector('span').textContent=on?__('بی‌صدا شده','Muted'):__('بی‌صدا','Mute');toast(on?__('اعلان‌های این گفتگو بی‌صدا شد','Notifications of this chat are muted'):__('اعلان‌ها دوباره روشن شد','Notifications are back on'),null,null,'info')}
      return;
    }
    if((b=e.target.closest('[data-mcpt]'))){cur=b.dataset.mcpt;paint();return}
    if((b=e.target.closest('[data-mcpm]'))){mcShowMedia(b.dataset.mcpm);return}
    if((b=e.target.closest('[data-mcf]'))){mcSaveMsg(b.dataset.mcf);return}
    if((b=e.target.closest('[data-mcpj]'))){
      var jid=b.dataset.mcpj;
      var after=function(){
        var r=document.querySelector('.kcx-row[data-mid="'+jid+'"]');
        if(r){r.scrollIntoView({block:'center',behavior:'smooth'});r.classList.remove('mc-flash');void r.offsetWidth;r.classList.add('mc-flash')}
      };
      if(history.state&&history.state.sub){history.back();setTimeout(after,380)}else{mcpKill();setTimeout(after,100)}
    }
  });
}
/* open a photo / video from the loaded messages (also used by the profile page) */
function mcShowMedia(sid){
  var sm=mcMsg(sid);if(!sm)return;
  var show=function(){spView([{id:sid,k:sm.kind==='p'?'p':'v',d:+(sm.meta&&sm.meta.d)||0,tid:'',ts:mcMs(sm.created_at)}],0)};
  if(SP.mem['sp_'+sid]){show();return}
  if(sm.kind==='r'&&VN.mem['vn_'+sid]){SP.mem['sp_'+sid]=VN.mem['vn_'+sid];show();return}
  if(!sm.media)return;
  toast(__('در حال بارگیری…','Loading…'),null,null,'info',1);
  mcBlob(sm.media,sm.kind!=='p').then(function(x){SP.mem['sp_'+sid]=x.u;show()}).catch(function(){toast(__('بارگیری نشد','Could not load'),null,null,'warn')});
}
/* tapping a PDF in a chat: «میخواهی PDF را باز کنی؟» بله / خیر + a tick above them «دیگر نپرس» (can be changed in settings › library) */
function pdfAskOn(){try{return localStorage.getItem('ario.pdfask')!=='0'}catch(e){return true}}
function pdfAskSet(on){try{localStorage.setItem('ario.pdfask',on?'1':'0')}catch(e){}}
function mcPdfAsk(m){
  if(!pdfAskOn()){lsImport(m,'pdf',true);return}
  var w=document.createElement('div');w.className='cfm-wrap';
  w.innerHTML='<div class="dim"></div><div class="cfm glass" role="alertdialog" aria-modal="true"><h3></h3><p dir="auto"></p>'+
    '<label class="cfm-ck"><input type="checkbox" id="pdfNo"><i></i><span>'+__('دیگر این سوال پرسیده نشود','Don’t ask this again')+'</span></label>'+
    '<div class="cfm-b cfm-yn"><button type="button" class="pri" data-y="1">'+__('بله','Yes')+'</button><button type="button" data-y="0">'+__('خیر','No')+'</button></div></div>';
  w.querySelector('h3').textContent=__('باز کردن PDF','Open the PDF');
  w.querySelector('p').textContent=__('می‌خواهی این PDF را باز کنی؟','Do you want to open this PDF?')+'\n'+lsTitle(m)+'.pdf';
  function close(fn){w.classList.remove('open');setTimeout(function(){w.remove()},300);document.removeEventListener('keydown',kd);if(fn)setTimeout(fn,60)}
  function kd(e){if(e.key==='Escape')close()}
  w.addEventListener('click',function(e){
    var b=e.target.closest('[data-y]');
    if(!b){if(e.target.classList.contains('dim'))close();return}
    if(b.dataset.y==='1'){var ck=w.querySelector('#pdfNo');if(ck&&ck.checked){pdfAskSet(false);toast(__('از این به بعد PDFها بدون پرسیدن باز می‌شوند. از تنظیمات › کتابخانه می‌توانی دوباره روشنش کنی.','PDFs now open without asking. You can turn this back on in Settings › Library.'),null,null,'info')}close(function(){lsImport(m,'pdf',true)})}
    else close();
  });
  document.addEventListener('keydown',kd);
  document.body.appendChild(w);
  requestAnimationFrame(function(){requestAnimationFrame(function(){w.classList.add('open')})});
}
function mcSaveFile(fm){
  toast(__('در حال بارگیری…','Loading…'),null,null,'info',1);
  mcBlob(fm.media,true).then(function(x){return mcSave(x.b,fm.mname||('file.'+mcExt(x.b,'')))}).catch(function(){toast(__('بارگیری نشد','Could not load'),null,null,'warn')});
}
function mcSaveMsg(id){
  var fm=mcMsg(id);if(!fm||!fm.media)return;
  var lk=lsKind(fm);if(lk==='pdf'){mcPdfAsk(fm);return}
  if(lk){lsOpen(fm,lk);return}
  toast(__('در حال بارگیری…','Loading…'),null,null,'info',1);
  mcBlob(fm.media,true).then(function(x){return mcSave(x.b,fm.mname||('file.'+mcExt(x.b,'')))}).catch(function(){toast(__('بارگیری نشد','Could not load'),null,null,'warn')});
}

function mcBackA(){
  mcStop();
  if(mcOpenNow()&&ui.mcFrom){ui.mcl=ui.mcFrom;ui.mcFrom=''}
  else{ui.mcl='';ui.mcFrom='';ui.tab=ui.mcTab||'coach'}
  render('enter');window.scrollTo(0,0);
}
actions.mcBack=function(){if(history.state&&history.state.sub){history.back();return}mcBackA()};
actions.mcDash=function(){var l=mcLink(ui.mcl);if(l)cdOpen(l.id)};

/* ---------- v343: voice chat (گفتگوی صوتی) in group and friend chats ----------
   The sound goes phone-to-phone (WebRTC, one connection to every other person, up to 8 people).
   Supabase only carries the small connection messages and the list of who is in (see the v343 and v344 blocks of supabase/setup.sql):
   voice_sync is called about once a second while someone is in the voice chat, voice_who every few seconds while a chat is open.
   To make it work on every mobile network a TURN server can be added: put it in VC_TURN, e.g. {urls:'turn:host:3478',username:'u',credential:'p'}. */
