  pdfv.pz={d0:d,z0:pdfv.zoom,z:pdfv.zoom,lx:mx,ly:my,mx:mx,my:my,raf:0};
  pdfv.pzUsed=1;pdfv.tap=0;pdfv.za=0;
  clearTimeout(pdfv.rfT);
  clearTimeout(pdfv.zmT);if(pdfv.el)pdfv.el.classList.add('zm');
