  p.raf=requestAnimationFrame(function(){
    p.raf=0;if(pdfv.pz!==p||!pdfv.pgs||!pdfv.sc)return;
    pvSetZoom(p.z,p.lx,p.ly,p.mx,p.my,true);
    p.lx=p.mx;p.ly=p.my;
  });
