/* stored strokes keep one entry per point at even positions (the others are curve mid-points) */
function inkVarPts(p){var o=[],i,n=p.length;if(n<=3)return p;for(i=0;i<n;i+=2)o.push(p[i]);if((n-1)%2)o.push(p[n-1]);return o}
/* fountain pen / brush / calligraphy: the stroke becomes a filled shape whose width follows speed, ends or direction */
function inkVarPoly(P,k,w){
  var n=P.length,i,ws=[],L=[],R=[],q,e,dx,dy,sp,t,a,len,h,r=Math.max(0.6,w/2);
  if(n<2){var x0=P[0][0],y0=P[0][1];return 'M'+inkR(x0-r)+' '+inkR(y0)+'a'+r+' '+r+' 0 1 0 '+(2*r)+' 0a'+r+' '+r+' 0 1 0 '+(-2*r)+' 0Z'}
  for(i=0;i<n;i++){
    q=P[Math.max(0,i-1)];e=P[Math.min(n-1,i+1)];dx=e[0]-q[0];dy=e[1]-q[1];
    sp=Math.sqrt(dx*dx+dy*dy)/(i>0&&i<n-1?2:1);
    t=Math.max(0,Math.min(1,(sp-1.5)/16));
    if(k==='fp')ws[i]=w*(1.3-0.9*t);
    else if(k==='br')ws[i]=w*(1.9-1.5*t)*(0.15+0.85*Math.min(1,(i+1)/7,(n-i)/10));
    else{a=Math.atan2(dy,dx);ws[i]=w*(0.18+1.25*Math.abs(Math.sin(a-0.785)))}
  }
  for(i=1;i<n;i++)ws[i]=ws[i-1]*0.5+ws[i]*0.5;
  for(i=n-2;i>=0;i--)ws[i]=ws[i+1]*0.5+ws[i]*0.5;
  for(i=0;i<n;i++){
    q=P[Math.max(0,i-1)];e=P[Math.min(n-1,i+1)];dx=e[0]-q[0];dy=e[1]-q[1];len=Math.sqrt(dx*dx+dy*dy)||1;h=Math.max(0.3,ws[i]/2);
    L.push(inkR(P[i][0]-dy/len*h)+' '+inkR(P[i][1]+dx/len*h));R.push(inkR(P[i][0]+dy/len*h)+' '+inkR(P[i][1]-dx/len*h));
  }
  return 'M'+L.join(' L')+' L'+R.reverse().join(' L')+'Z';
}
