function inkHasAlpha(c){
  try{
    var s=Math.min(1,128/Math.max(c.width,c.height)),w=Math.max(1,Math.round(c.width*s)),h=Math.max(1,Math.round(c.height*s)),t=document.createElement('canvas');
    t.width=w;t.height=h;var x=t.getContext('2d');x.drawImage(c,0,0,w,h);
    var d=x.getImageData(0,0,w,h).data,n=0,i;
    for(i=3;i<d.length;i+=4)if(d[i]<200)n++;
    return n>w*h*0.03;
  }catch(e){return false}
}
/* asks whether to keep the photo as it is or cut the subject out; resolves {canvas,png} or null (cancel) */
function inkBgAsk(c){
  return new Promise(function(res){
    var w=document.createElement('div');w.className='cfm-wrap bgrw';
    w.innerHTML='<div class="dim"></div><div class="cfm bgr" role="dialog" aria-modal="true"><div class="bgr-pv glass scan"><div class="bgr-st"><i class="bgr-ln"></i></div></div><p class="bgr-t" aria-live="polite"></p><div class="cfm-b"></div></div>';
    var pv=w.querySelector('.bgr-pv'),tx=w.querySelector('.bgr-t'),box=w.querySelector('.cfm-b'),done=false,cut=null;
    var st=pv.firstChild;st.insertBefore(c,st.firstChild);
    tx.textContent=__("در حال بارگذاری…","Loading…");
    function setT(v){tx.classList.remove('bgr-fd');void tx.offsetWidth;tx.textContent=v;tx.classList.add('bgr-fd')}
    function close(r){if(done)return;done=true;w.classList.remove('open');setTimeout(function(){w.remove()},300);document.removeEventListener('keydown',kd);res(r)}
    function kd(e){if(e.key==='Escape')close(null)}
    /* the scan line sweeps again: above it the subject is cut out (background gone), below it is still the photo */
    function wipe(){
      box.classList.add('bgr-off');setT(__("در حال حذف پس‌زمینه…","Removing background…"));
      var f=cut._full;f.className='bgr-cut';st.appendChild(f);pv.classList.add('cutting');
      var ln=st.querySelector('.bgr-ln'),t0=performance.now(),D=850;
      function fr(now){
        if(done)return;
        var k=Math.min(1,(now-t0)/D),y=(k*100).toFixed(2);
        c.style.clipPath='inset('+y+'% 0 0 0)';f.style.clipPath='inset(0 0 '+(100-k*100).toFixed(2)+'% 0)';ln.style.top='calc('+y+'% - '+(k*3).toFixed(2)+'px)';
        if(k<1)requestAnimationFrame(fr);
        else close({canvas:cut,png:true})
      }
      pv.classList.add('scan');requestAnimationFrame(fr);
    }
    var st;
    function btn(t,cls,fn){var b=document.createElement('button');b.type='button';if(cls)b.className=cls;b.textContent=t;b.addEventListener('click',fn);box.appendChild(b)}
    w.querySelector('.dim').addEventListener('click',function(){close(null)});
    document.addEventListener('keydown',kd);
    document.body.appendChild(w);
    requestAnimationFrame(function(){requestAnimationFrame(function(){
      w.classList.add('open');
      setTimeout(function(){
        if(done)return;
        /* a picture that already has a transparent background (PNG cut-out): just load it, no question */
        if(inkHasAlpha(c)){setTimeout(function(){close({canvas:c,png:true})},550);return}
        try{cut=inkCutout(c)}catch(e){cut=null}
        var t0=Date.now();
        /* let the scan line finish at least one sweep so it feels intentional, but never longer than ~0.9s */
        setTimeout(function(){
          if(done)return;
          pv.classList.remove('scan');
          if(cut){
            setT(__("می‌خواهی همین عکس اضافه شود یا بدون پس‌زمینه؟","Add this photo as it is, or without its background?"));
            btn(__("بدون پس‌زمینه","Remove background"),'pri',function(){wipe()});
            btn(__("همین عکس","Keep as it is"),'',function(){close({canvas:c,png:false})});
          }else{
            setT(__("پس‌زمینهٔ این عکس به‌صورت خودکار جدا نشد؛ همین عکس اضافه شود؟","The background could not be separated automatically. Add the photo as it is?"));
            btn(__("همین عکس","Keep as it is"),'pri',function(){close({canvas:c,png:false})});
          }
          btn(__("انصراف","Cancel"),'',function(){close(null)});
        },Math.max(0,700-(Date.now()-t0)));
      },60);
    })});
  });
}
async function inkPutCanvas(c,png){
  var b=await new Promise(function(r){c.toBlob(function(x){r(x)},png?'image/png':'image/jpeg',png?undefined:0.86)}),k=imNewId();
  if(!b)throw new Error('invalid');
  await fdbPut('ni_'+k,{full:b});
  inkImgU[k]=URL.createObjectURL(b);
  return {k:k,w:c.width,h:c.height};
}
async function inkInsertImg(file,off){
  off=off||0;
  if(!pdfv.on)return;
  try{
    var base=imToCanvas(await imLoad(file),1600),ch=await inkBgAsk(base);
    if(!ch||!pdfv.on)return;
    var m=await inkPutCanvas(ch.canvas,ch.png),i=Math.max(0,Math.min(pdfv.n-1,pvCur()-1)),W=Math.min(560,Math.max(240,m.w/2)),Hh=W*m.h/m.w,H=1000*pdfv.rat[i];
    if(Hh>H*0.8){Hh=H*0.8;W=Hh*m.w/m.h}
    var it={t:'i',k:m.k,x:Math.round((1000-W)/2+off*36),y:Math.round(Math.max(30,(H-Hh)/3)+off*36),w:Math.round(W),h:Math.round(Hh)};
    inkAdd(i,it);pvTool('lasso');inkSet(i,[it]);
  }catch(e){toast('افزودن عکس ممکن نشد',null,null,'warn')}
}
async function inkInsertFromLib(id,off){
  try{
    var r=await fdbGet(id);if(!r||!r.full)throw new Error('missing');
    await inkInsertImg(r.full,off);
  }catch(e){toast('افزودن عکس ممکن نشد',null,null,'warn')}
}
/* ---------- toolbar actions, panels ---------- */
var PV_TOOLS=['hand','pen','hl','er','lasso','text'];
/* quick switch for the two erasers: two round buttons float at the left while the eraser tool is active
   (checkerboard = area eraser: only the part you drag over disappears, as if painted with the page colour; eraser = whole-stroke eraser) */
function pvEqs(on){
  var el=pdfv.el;if(!el)return;
  var g=el.querySelector('.ink-eqs');
  if(!g){
    g=document.createElement('div');g.className='ink-eqs';g.setAttribute('role','group');g.setAttribute('aria-label',__('نوع پاک‌کن','Eraser type'));
    g.innerHTML='<button type="button" class="ink-eq" data-pv="em" data-v="area" aria-label="'+__('پاک‌کن ناحیه (فقط جایی که می‌کشی)','Area eraser (only where you drag)')+'"><svg viewBox="0 0 24 24" class="ic" aria-hidden="true"><g fill="currentColor" stroke="none"><rect x="3" y="3" width="4" height="4"/><rect x="11" y="3" width="4" height="4"/><rect x="19" y="3" width="2" height="4"/><rect x="7" y="7" width="4" height="4"/><rect x="15" y="7" width="4" height="4"/><rect x="3" y="11" width="4" height="4"/><rect x="11" y="11" width="4" height="4"/><rect x="19" y="11" width="2" height="4"/><rect x="7" y="15" width="4" height="4"/><rect x="15" y="15" width="4" height="4"/><rect x="3" y="19" width="4" height="2"/><rect x="11" y="19" width="4" height="2"/><rect x="19" y="19" width="2" height="2"/></g></svg></button>'+
      '<button type="button" class="ink-eq" data-pv="em" data-v="stroke" aria-label="'+__('پاک‌کن خط (کل خط)','Stroke eraser (whole stroke)')+'">'+icon('eraser')+'</button>';
    el.appendChild(g);
  }
  if(on!==undefined)g.classList.toggle('on',!!on);
  [].forEach.call(g.querySelectorAll('.ink-eq'),function(b){b.setAttribute('aria-pressed',String(b.dataset.v===pdfv.em))});
  g.style.setProperty('--ei',pdfv.em==='area'?0:1);
}
function pvTool(t){
  if(PV_TOOLS.indexOf(t)<0||!pdfv.el)return;
  if(t!=='lasso')inkSelClear();
  if(t!=='hand'&&pdfv.ts)tsClear();
  if(t!=='hand')pdfv.last=t;
  pdfv.tool=t;
  pdfv.el.classList.toggle('dr',t!=='hand');
  pvEqs(t==='er');
  pdfv.el.querySelectorAll('[data-pv^="t-"]').forEach(function(b){b.setAttribute('aria-pressed',b.dataset.pv==='t-'+t)});
  pvWPaint();
  if(pdfv.pop==='tools')pvPopRender();
}
