  for(n=1;n<N;n++)xs+=('0000000000'+xr[n]).slice(-10)+' 00000 n \n';
  put(xs+'trailer\n<</Size '+N+'/Root 1 0 R>>\nstartxref\n'+xo+'\n%%EOF');
