/* ---------- دست‌خط به متن و جستجو در نوشته‌ها (library OCR) ----------
   OFF by default (Account > Settings). Uses the same offline Persian engine as the table scan (scWorker).
   Each handwritten page is cut into text lines (by ink position), every line is read on its own, and the text is kept
   in the page itself (page.ox = text, page.oh = stroke signature, so a changed page is known to be out of date).
   A small index (IndexedDB key 'ntx': note id -> [[page, text]]) lets the note list search inside the writing. */
function ocrOn(){try{return localStorage.getItem('ario_inkocr')==='1'}catch(e){return false}}
function ocrSet(on){try{if(on)localStorage.setItem('ario_inkocr','1');else localStorage.removeItem('ario_inkocr')}catch(e){}}
var ntx=null,ntxP=null,ocrBusy=false;
function ntxLoad(){
  if(ntx)return Promise.resolve(ntx);
  if(!ntxP)ntxP=fdbGet('ntx').then(function(r){ntx=(r&&r.m&&typeof r.m==='object'&&!Array.isArray(r.m))?r.m:{};return ntx}).catch(function(){ntx={};return ntx});
  return ntxP;
}
function ntxSave(){if(ntx)fdbPut('ntx',{m:ntx}).catch(function(){})}
/* make the index of one note match its pages (page numbers always follow the real page order) */
function ntxSync(id,doc){
  ntxLoad().then(function(m){
    var a=[];(doc.pages||[]).forEach(function(p,i){if(p&&typeof p.ox==='string'&&p.ox)a.push([i,p.ox])});
    if(JSON.stringify(a)===JSON.stringify(m[id]||[]))return;
    if(a.length)m[id]=a;else delete m[id];
    ntxSave();
  });
}
function ocrStrokes(pg){return (pg&&Array.isArray(pg.s)?pg.s:[]).filter(function(it){return it&&it.t==='p'&&typeof it.d==='string'&&/^[MLQ0-9., -]+$/.test(it.d)})}
function ocrSig(pg){var st=ocrStrokes(pg),n=0;st.forEach(function(it){n+=it.d.length});return st.length+':'+n}
function ocrStale(pg){return ocrStrokes(pg).length>0&&pg.oh!==ocrSig(pg)}
