async function ocrBands(pg){
  var st=ocrStrokes(pg);if(!st.length)return [];
  var inf=st.map(function(it){var b=inkBBox(it,-1);return {it:it,b:b,h:b[3]-b[1]}}).filter(function(s){return s.b[2]>s.b[0]||s.b[3]>s.b[1]});
  inf.sort(function(a,b){return a.b[1]-b[1]});
  var bands=[];
  inf.forEach(function(s){
    var c=bands[bands.length-1];
    if(c&&Math.min(c.y1,s.b[3])-s.b[1]>0.3*Math.min(s.h,c.y1-c.y0)){c.s.push(s);c.y1=Math.max(c.y1,s.b[3]);c.y0=Math.min(c.y0,s.b[1])}
    else bands.push({s:[s],y0:s.b[1],y1:s.b[3]});
  });
  var Hb=inkMed(bands.map(function(b){return b.y1-b.y0}));
  /* dots or marks that ended up alone join the nearest line */
  var k,j,best,bd,c2,d;
  for(k=bands.length-1;k>=0;k--){
    c2=bands[k];if(bands.length<2||c2.y1-c2.y0>=0.45*Hb)continue;
    best=-1;bd=1.2*Hb;
    for(j=0;j<bands.length;j++){if(j===k)continue;d=Math.max(0,Math.max(c2.y0,bands[j].y0)-Math.min(c2.y1,bands[j].y1));if(d<bd){bd=d;best=j}}
    if(best>=0){var t=bands[best];t.s=t.s.concat(c2.s);t.y0=Math.min(t.y0,c2.y0);t.y1=Math.max(t.y1,c2.y1);bands.splice(k,1)}
  }
  var out=[];
  for(k=0;k<bands.length;k++){
    var bd2=bands[k],x0=1e9,x1=-1e9,y0=1e9,y1=-1e9;
    bd2.s.forEach(function(s){x0=Math.min(x0,s.b[0]);x1=Math.max(x1,s.b[2]);y0=Math.min(y0,s.b[1]);y1=Math.max(y1,s.b[3])});
    x0-=14;y0-=12;x1+=14;y1+=12;
    var w=x1-x0,h=y1-y0,sc=Math.max(0.6,Math.min(4,90/h));sc=Math.min(sc,2800/w);
    var cv=document.createElement('canvas');cv.width=Math.max(8,Math.round(w*sc));cv.height=Math.max(8,Math.round(h*sc));
    var cx=cv.getContext('2d');cx.fillStyle='#fff';cx.fillRect(0,0,cv.width,cv.height);
    var its=bd2.s.map(function(s){return {t:'p',c:'#000000',w:Math.max(+s.it.w||4,3.5/sc),d:dMap(s.it.d,function(x,y){return [x-x0,y-y0]})}});
    await inkDrawItems(cx,its,sc,false);
    cv._o={x0:x0,y0:y0,sc:sc};out.push(cv);
  }
  return out;
}
/* read several pages with one engine; pages = [page objects]; returns [text,…] (same order) */
async function ocrRun(pages,say,dead){
  var w=null,out=[],k,j;
  try{
    say(__("در حال آماده‌سازی موتور تشخیص…","Preparing the recognition engine…"));
    w=await scWorker(function(){});
    await w.setParameters({tessedit_pageseg_mode:'7',preserve_interword_spaces:'1'});
    for(k=0;k<pages.length;k++){
      if(dead())break;
      say(pages.length>1?__("در حال خواندن صفحهٔ","Reading page")+' '+fa(k+1)+' '+__("از","of")+' '+fa(pages.length)+'…':__("در حال خواندن دست‌خط…","Reading the handwriting…"));
      var bands=await ocrBands(pages[k]),lines=[];
      for(j=0;j<bands.length;j++){
        if(dead())break;
        var r=await w.recognize(bands[j]),t=ocrClean(r&&r.data&&r.data.text);
        if(t.length>=2&&((r.data&&r.data.confidence)||0)>=20)lines.push(t);
      }
      out.push(lines.join('\n'));
    }
  }finally{if(w){try{await w.terminate()}catch(e){}}}
  return out;
}
function ocrFail(e){
  toast(String(e&&e.message)==='ocr-offline'?__("بار اول برای گرفتن موتور تشخیص متن اینترنت لازم است.","The first time needs the internet to get the recognition engine."):__("تبدیل دست‌خط به متن انجام نشد.","Could not convert the handwriting."),null,null,'warn');
}
function ocrDlg(title){
  var w=document.createElement('div');w.className='cfm-wrap';
  w.innerHTML='<div class="dim"></div><div class="cfm glass" role="dialog" aria-modal="true"><h3></h3><p class="hint ocr-st" aria-live="polite"></p><textarea class="field ink-ta ocr-ta" rows="7" maxlength="3000" dir="auto" style="display:none"></textarea><div class="cfm-b"></div></div>';
  w.querySelector('h3').textContent=title;
  var st=w.querySelector('.ocr-st'),ta=w.querySelector('textarea'),box=w.querySelector('.cfm-b'),dead=false;
  function close(){if(dead)return;dead=true;w.classList.remove('open');setTimeout(function(){w.remove()},300)}
  document.body.appendChild(w);
  requestAnimationFrame(function(){requestAnimationFrame(function(){w.classList.add('open')})});
  return {ta:ta,close:close,dead:function(){return dead},
    say:function(t){st.textContent=t},
    show:function(t){ta.style.display='';ta.value=t},
    btns:function(a){box.innerHTML='';a.forEach(function(b){var e=document.createElement('button');e.type='button';if(b[2])e.className='pri';e.textContent=b[0];e.addEventListener('click',b[1]);box.appendChild(e)})}};
}
/* keep the read text in the note (open note: saved with the next autosave; closed note: written straight to the database) */
async function ocrPersist(rec,doc){
  if(pdfv.on&&pdfv.doc===doc){anLater();ntxSync(rec.id,doc);return}
  try{var r=await fdbGet('nt_'+rec.id);await fdbPut('nt_'+rec.id,{doc:doc,thumb:(r&&r.thumb)||null})}catch(e){}
  ntxSync(rec.id,doc);
}
function ocrAskOn(fn){
  toast(__("تبدیل دست‌خط به متن خاموش است. از حساب ← تنظیمات روشنش کن.","Handwriting to text is off. Turn it on in Account › Settings."),__("روشن کن","Turn on"),function(){ocrSet(true);fn()},'info',true);
}
async function ocrPage(){
  if(pdfv.kind!=='note'||!pdfv.doc||!pdfv.rec)return;
  pvPopSet('');
  if(!ocrOn()){ocrAskOn(ocrPage);return}
  if(ocrBusy){toast(__("یک تبدیل دیگر در حال انجام است.","Another conversion is running."),null,null,'info');return}
  var doc=pdfv.doc,rec=pdfv.rec,idx=Math.max(0,Math.min(pdfv.n-1,pvCur()-1)),pg=doc.pages[idx];
  if(!ocrStrokes(pg).length){toast(__("در این صفحه نوشتهٔ دست‌نویس نیست.","There is no handwriting on this page."),null,null,'info');return}
  ocrBusy=true;
  var cancel=false,D=ocrDlg(__("دست‌خط به متن","Handwriting to text"));
  D.btns([[__("انصراف","Cancel"),function(){cancel=true;D.close()}]]);
  try{
    var r=await ocrRun([pg],D.say,function(){return cancel});
    if(cancel)return;
    var text=r[0]||'';
    D.say(text?__("اگر جایی غلط خوانده شده، همین‌جا درستش کن. دست‌خط، به‌خصوص پیوسته، همیشه درست خوانده نمی‌شود.","Fix anything that was misread. Handwriting, especially joined-up, is not always read correctly."):__("نوشته‌ای خوانده نشد. با خط درشت‌تر و جدا از هم بهتر می‌شود.","Nothing could be read. Larger, clearer writing works better."));
    D.show(text);
    D.btns([
      [__("ذخیره برای جستجو","Save for search"),function(){
        var v=D.ta.value.trim().slice(0,3000);
        if(v){pg.ox=v;pg.oh=ocrSig(pg)}else{delete pg.ox;delete pg.oh}
        ocrPersist(rec,doc);D.close();toast(v?__("برای جستجو ذخیره شد.","Saved for search."):__("متن این صفحه پاک شد.","This page's text was cleared."),null,null,'ok',true);
      },1],
      [__("افزودن به صفحه","Add to page"),function(){
        var v=D.ta.value.trim();if(!v||!pdfv.on||pdfv.doc!==doc)return;
        var y=40,b;ocrStrokes(pg).forEach(function(it){b=inkBBox(it,-1);y=Math.max(y,b[3]+30)});
        var H=1000*pg.r,last=inkTxLast(),it2={t:'x',c:pdfv.col,s:v,f:last.f,x:80,y:Math.round(Math.min(y,Math.max(40,H-140))),r:/[\u0590-\u08FF]/.test(v)?1:0};
        inkTxApply(it2,last);inkAdd(idx,it2);pg.ox=v;pg.oh=ocrSig(pg);anLater();ntxSync(rec.id,doc);D.close();
      }],
      [__("کپی","Copy"),function(){
        var v=D.ta.value;
        try{navigator.clipboard.writeText(v).then(function(){toast(__("کپی شد.","Copied."),null,null,'ok',true)},function(){D.ta.select();document.execCommand('copy')})}catch(e){try{D.ta.select();document.execCommand('copy')}catch(x){}}
      }],
      [__("بستن","Close"),function(){D.close()}]
    ]);
  }catch(e){D.close();ocrFail(e)}
  finally{ocrBusy=false}
}
async function ocrAllNote(){
  if(pdfv.kind!=='note'||!pdfv.doc||!pdfv.rec)return;
  pvPopSet('');
  if(!ocrOn()){ocrAskOn(ocrAllNote);return}
  if(ocrBusy){toast(__("یک تبدیل دیگر در حال انجام است.","Another conversion is running."),null,null,'info');return}
  var doc=pdfv.doc,rec=pdfv.rec,todo=doc.pages.filter(ocrStale);
  if(!todo.length){toast(__("همهٔ صفحه‌های این یادداشت از قبل فهرست شده‌اند.","All pages of this note are already indexed."),null,null,'info');return}
  ocrBusy=true;
  var cancel=false,D=ocrDlg(__("فهرست‌کردن برای جستجو","Indexing for search"));
  D.btns([[__("انصراف","Cancel"),function(){cancel=true;D.close()}]]);
  try{
    var r=await ocrRun(todo,D.say,function(){return cancel||D.dead()}),n=0,done=0;
    r.forEach(function(t,k){if(t){todo[k].ox=t.slice(0,3000);n++}else{delete todo[k].ox}todo[k].oh=ocrSig(todo[k]);done++});
    if(done)ocrPersist(rec,doc);
    D.close();
    toast(n?fa(n)+' '+__("صفحه فهرست شد.","pages indexed."):__("نوشته‌ای خوانده نشد.","Nothing could be read."),null,null,n?'ok':'info',true);
  }catch(e){D.close();ocrFail(e)}
  finally{ocrBusy=false}
}
/* quietly index the changed pages of a note that was just closed (at most 8 pages at a time) */
async function ocrAuto(rec,doc){
  if(!ocrOn()||ocrBusy||!rec||!doc||!Array.isArray(doc.pages))return;
  var todo=doc.pages.filter(ocrStale).slice(0,8);if(!todo.length)return;
  var sigs=todo.map(ocrSig);
  ocrBusy=true;
  try{
    var r=await ocrRun(todo,function(){},function(){return pdfv.on&&pdfv.rec&&pdfv.rec.id===rec.id||!ocrOn()});
    if(pdfv.on&&pdfv.rec&&pdfv.rec.id===rec.id)return;     /* note reopened: leave it to the writer */
    var n=0;
    r.forEach(function(t,k){if(ocrSig(todo[k])!==sigs[k])return;if(t)todo[k].ox=t.slice(0,3000);else delete todo[k].ox;todo[k].oh=sigs[k];n++});
    if(n){var rr=await fdbGet('nt_'+rec.id);await fdbPut('nt_'+rec.id,{doc:doc,thumb:(rr&&rr.thumb)||null});ntxSync(rec.id,doc)}
  }catch(e){}
  finally{ocrBusy=false}
}
/* notes whose writing contains the (normalised) text q: id -> {p: page number, sn: the matching line} */
function ntxFind(q){
  var out={};if(!ntx||!q)return out;
  Object.keys(ntx).forEach(function(id){
    var a=ntx[id],k,ls,j,ln;
    for(k=0;k<a.length;k++){
      ls=String(a[k][1]).split('\n');
      for(j=0;j<ls.length;j++){
        ln=ls[j];
        if(ntNorm(ln).indexOf(q)>=0){out[id]={p:a[k][0]+1,sn:ln.length>70?ln.slice(0,70)+'…':ln};return}
      }
      if(ntNorm(a[k][1].replace(/\n/g,' ')).indexOf(q)>=0){out[id]={p:a[k][0]+1,sn:a[k][1].replace(/\n/g,' ').slice(0,70)};return}
    }
  });
  return out;
}
function ntListHTML(){
  if(ui.ntbin)return ntBinHTML();
  ntBinPurge();
  var NT=tbD().notes,nb=tbD().bin.length,binBtn=nb?'<button type="button" class="btn bk-add2" data-act="ntBin" data-v="1">'+icon('trash')+__("سطل بازیافت","Recycle bin")+' ('+fa(nb)+')</button>':'';
  if(ocrOn()&&!ntx)ntxLoad().then(function(){if(ui.ntq)ntPaint()});
  var add='<button type="button" class="btn bk-add" data-act="ntNew">'+icon('plus')+__("یادداشت تازه","New note")+'</button>';
  if(!NT.length)return add+binBtn+'<div class="empty"><div class="badge">'+icon('pen')+'</div><h3>'+__("هنوز یادداشتی نیست","No notes yet")+'</h3><p>'+__("یک دفترچهٔ دست‌نویس بساز؛ با قلم، ماژیک، پاک‌کن و قالب‌های خط‌دار و شطرنجی.","Create a handwritten notebook with pen, highlighter, eraser and lined or grid paper.")+'</p></div>';
  return add+binBtn+'<div class="ttl-qw nt-q">'+icon('search')+'<input class="field ttl-q" id="ntQ" type="search" enterkeyhint="search" autocomplete="off" value="'+esc(ui.ntq||'')+'" placeholder="'+(ocrOn()?__("جستجو در نام و نوشتهٔ یادداشت‌ها","Search note names and writing"):__("جستجوی یادداشت‌ها","Search notes"))+'" aria-label="'+__("جستجوی یادداشت‌ها","Search notes")+'"></div>'+
    '<div id="ntSort">'+ntSortHTML()+'</div>'+
    '<h3 class="gh"><span>'+__("یادداشت‌های من","My notes")+'</span><span>'+fa(NT.length)+'</span></h3><div id="ntRes">'+ntRowsHTML()+'</div>';
}
function ntPaint(){var r=$('#ntRes');if(r){r.innerHTML=ntRowsHTML();tbFill()}var s=$('#ntSort');if(s)s.innerHTML=ntSortHTML()}
function bkPaint(){var r=$('#bkRes');if(r){r.innerHTML=tbBkRowsHTML();tbFill()}}
document.addEventListener('input',function(e){if(e.target&&e.target.id==='bkQ'){ui.bkq=e.target.value;bkPaint()}});
actions.bkSelOn=function(){ui.bkSel={};bkPaint()};
actions.bkSelOff=function(){ui.bkSel=null;bkPaint()};
actions.bkSelAll=function(){
  var S=ui.bkSel||(ui.bkSel={});
  document.querySelectorAll('#bkRes [data-act="bkTog"]').forEach(function(b){S[b.dataset.k+':'+b.dataset.v]=1});
  bkPaint();
};
actions.bkTog=function(d){
  var S=ui.bkSel;if(!S)return;
  var k=d.k+':'+d.v;if(S[k])delete S[k];else S[k]=1;
  bkPaint();
};
function bkSelItems(){
  var out=[];
  Object.keys(ui.bkSel||{}).forEach(function(key){
    var k=key.charAt(0),id=key.slice(2),list=k==='i'?'imgs':'pdfs',rec=tbD()[list].find(function(x){return x.id===id});
    if(rec)out.push({k:k,list:list,rec:rec});
  });
  return out;
}
actions.bkSelAct=function(d){
  var it=bkSelItems();if(!it.length)return;
  var a=d.v;
  if(a==='share'){tbShareFiles(it);return}
  if(a==='cat'){
    var cv=it[0].rec.c||'';it.forEach(function(x){if((x.rec.c||'')!==cv)cv=''});
    askCat({title:__("دسته‌بندی درسی","Subject"),val:cv,fn:function(v){
      it.forEach(function(x){x.rec.c=v});persist();ui.bkSel=null;bkPaint();
    }});
    return;
  }
  if(a==='star'){
    var all=it.every(function(x){return x.rec.st});
    it.forEach(function(x){x.rec.st=all?0:1});persist();ui.bkSel=null;bkPaint();return;
  }
  if(a==='del'){
    ui.bkSel=null;
    tbSoftDelMany(it.map(function(x){return {list:x.list,rec:x.rec,clean:function(){if(x.k==='i')tbCleanImg(x.rec);else tbCleanPdf(x.rec)}}}),
      EN?it.length+' items deleted':fa(it.length)+' مورد حذف شد');
  }
};
/* share: PDFs are the original files copied to the cache, photos are written from the file store; several at once go in one share sheet */
function tbSafeName(n,ext,used){
  var b=String(n||'file').replace(/[\\\/:*?"<>|\s]+/g,'-').slice(0,40)||'file',nm=b+ext,i=2;
  while(used[nm])nm=b+'-'+(i++)+ext;
  used[nm]=1;return nm;
}
async function tbShareFiles(items){
  var FS=capGet('Filesystem'),SH=capGet('Share');
  if(!FS||!SH){toast(__("ارسال فایل فقط در برنامهٔ اندروید ممکن است","Sharing files works in the Android app only"),null,null,'info');return}
  toast(__("در حال آماده‌سازی…","Preparing…"),null,null,'info');
  var uris=[],used={},title=items.length===1?items[0].rec.n:__("فایل‌های برنامه‌یار","Barnameyar files");
  try{
    for(var i=0;i<items.length;i++){
      var x=items[i],rec=x.rec,nm;
      if(x.k==='i'){
        var r=await fdbGet(rec.id);if(!r||!r.full)continue;
        var ext=/png/.test(r.full.type||'')?'.png':'.jpg';nm=tbSafeName(rec.n,ext,used);
        var b64=await new Promise(function(res,rej){var fr=new FileReader();fr.onload=function(){res(String(fr.result).split(',')[1])};fr.onerror=rej;fr.readAsDataURL(r.full)});
        var w=await FS.writeFile({path:nm,data:b64,directory:'CACHE'});uris.push(w.uri);
      }else{
        nm=tbSafeName(rec.n,'.pdf',used);
        var c=await FS.copy({from:'pdfs/'+rec.id+'.pdf',directory:'DATA',to:nm,toDirectory:'CACHE'});uris.push(c.uri);
      }
    }
    if(!uris.length){toast(__("فایلی برای ارسال پیدا نشد","No file to share"),null,null,'warn');return}
    if(uris.length===1)await SH.share({title:title,url:uris[0],dialogTitle:title});
    else await SH.share({title:title,files:uris,dialogTitle:title});
    if(ui.bkSel){ui.bkSel=null;if(ui.tab==='tb')bkPaint()}
  }catch(e){
    if(/cancel/i.test(String(e&&e.message||e)))return;
    toast(__("ارسال فایل ممکن نشد","Could not share the file"),null,null,'warn');
  }
}
actions.bkCat=function(d){ui.bkc=d.v||'';bkPaint()};
actions.bkSort=function(d){ui.bks=d.v;bkPaint()};
actions.bkStar=function(d){
  var rec=(d.k==='i'?tbD().imgs:tbD().pdfs).find(function(x){return x.id===d.v});if(!rec)return;
  rec.st=rec.st?0:1;persist();bkPaint();
};
actions.tbCat=function(d){
  var rec=(d.k==='i'?tbD().imgs:tbD().pdfs).find(function(x){return x.id===d.v});if(!rec)return;
  askCat({title:__("دسته‌بندی درسی","Subject"),val:rec.c||'',fn:function(v){var x=(d.k==='i'?tbD().imgs:tbD().pdfs).find(function(q){return q.id===rec.id});if(x){x.c=v;mutate()}}});
};
/* subject picker (same look as askText) */
function askCat(o){
  var w=document.createElement('div');w.className='cfm-wrap';
  w.innerHTML='<div class="dim"></div><div class="cfm glass" role="dialog" aria-modal="true"><h3></h3><div class="cat-grid"></div><div class="cfm-b"></div></div>';
  w.querySelector('h3').textContent=o.title||'';
  function close(fn){w.classList.remove('open');setTimeout(function(){w.remove()},300);document.removeEventListener('keydown',kd);if(fn)setTimeout(fn,60)}
  function kd(e){if(e.key==='Escape')close()}
  var g=w.querySelector('.cat-grid');
  LIB_CATS.forEach(function(c){var b=document.createElement('button');b.type='button';b.textContent=__(c);if(o.val===c)b.className='on';b.addEventListener('click',function(){close(function(){o.fn(c)})});g.appendChild(b)});
  var box=w.querySelector('.cfm-b');
  if(o.val){var b1=document.createElement('button');b1.type='button';b1.className='bad';b1.textContent=__("برداشتن دسته","Remove subject");b1.addEventListener('click',function(){close(function(){o.fn('')})});box.appendChild(b1)}
  var b2=document.createElement('button');b2.type='button';b2.textContent=__("انصراف");b2.addEventListener('click',function(){close()});box.appendChild(b2);
  w.querySelector('.dim').addEventListener('click',function(){close()});
  document.addEventListener('keydown',kd);
  document.body.appendChild(w);
  requestAnimationFrame(function(){requestAnimationFrame(function(){w.classList.add('open')})});
}
document.addEventListener('input',function(e){if(e.target&&e.target.id==='ntQ'){ui.ntq=e.target.value;ntPaint()}});
actions.ntSort=function(d){ui.nts=d.v;ntPaint()};
actions.ntPin=function(d){var b=tbD().notes.find(function(x){return x.id===d.v});if(!b)return;b.pin=b.pin?0:1;persist();ntPaint()};
actions.ntDup=async function(d){
  var D=tbD(),b=D.notes.find(function(x){return x.id===d.v});if(!b)return;
  if(D.notes.length>=200){toast('حداکثر ۲۰۰ یادداشت',null,null,'warn');return}
  try{
    var r=await fdbGet('nt_'+b.id);if(!r||!r.doc)throw new Error('missing');
    var doc=JSON.parse(JSON.stringify(r.doc)),id=imNewId(),pgs=doc.pages||[],q,k,s,nk,im;
    for(q=0;q<pgs.length;q++)for(k=0;k<(pgs[q].s||[]).length;k++){
      s=pgs[q].s[k];
      if(s&&s.t==='i'&&typeof s.k==='string'){im=await fdbGet('ni_'+s.k);nk=imNewId();if(im&&im.full){await fdbPut('ni_'+nk,{full:im.full});s.k=nk}}
    }
    await fdbPut('nt_'+id,{doc:doc,thumb:r.thumb||null});
    ntxSync(id,doc);
    var nn=(b.n+' '+__("(کپی)","(copy)")).slice(0,60),now=Date.now();
    D.notes.unshift({id:id,n:nn,pg:b.pg,lp:1,ad:now,md:now,pin:0});
    mutate();toast(__("یادداشت کپی شد","Note duplicated"));
  }catch(e){toast('کپی یادداشت ممکن نشد',null,null,'warn')}
};
actions.tbsec=function(d){ui.ntbin=false;ui.tbsec=d.v;render('swap')};
actions.ntNew=async function(){
  var D=tbD();
  if(D.notes.length>=200){toast('حداکثر ۲۰۰ یادداشت',null,null,'warn');return}
  var id=imNewId(),rec={id:id,n:__("یادداشت","Note")+' '+fa(D.notes.length+1),pg:1,lp:1,ad:Date.now(),md:Date.now()};
  try{await fdbPut('nt_'+id,{doc:{v:1,pages:[{t:'grid',r:INK_PORT,p:'#ffffff',s:[]}]},thumb:null})}catch(e){toast('ساخت یادداشت ممکن نشد',null,null,'warn');return}
  D.notes.unshift(rec);persist();
  actions.ntOpen({v:id});
};
actions.ntRen=function(d){
  var b=tbD().notes.find(function(x){return x.id===d.v});if(!b)return;
  askText({title:__("تغییر نام","Rename"),val:b.n,btn:__("ذخیره","Save"),fn:function(v){
    v=String(v||'').replace(/[<>&"']/g,'').trim().slice(0,60);if(!v)return;
    var x=tbD().notes.find(function(q){return q.id===b.id});if(x){x.n=v;mutate()}
  }});
};
/* really remove a note's data (pages, photos, search text) */
async function ntWipe(id){
  try{
    var r=await fdbGet('nt_'+id);
    if(r&&r.doc&&Array.isArray(r.doc.pages))r.doc.pages.forEach(function(p){(p.s||[]).forEach(function(s){if(s&&s.t==='i'&&typeof s.k==='string')fdbDel('ni_'+s.k).catch(function(){})})});
  }catch(e){}
  fdbDel('nt_'+id).catch(function(){});
  fdbDel('nv_'+id).catch(function(){});
  ntxLoad().then(function(m){if(m[id]){delete m[id];ntxSave()}});
  if(imURL['nt_'+id]){URL.revokeObjectURL(imURL['nt_'+id]);delete imURL['nt_'+id]}
}
/* deleted notes wait 30 days in the recycle bin (their data stays in place), then they are wiped */
var NT_BIN_DAYS=30;
function ntBinPurge(){
  var D=tbD(),lim=Date.now()-NT_BIN_DAYS*86400000,gone=D.bin.filter(function(b){return b.dt<lim});
  if(!gone.length)return;
  D.bin=D.bin.filter(function(b){return b.dt>=lim});
  gone.forEach(function(b){ntWipe(b.id)});
  persist();
}
actions.ntDel=function(d){
  var b=tbD().notes.find(function(x){return x.id===d.v});if(!b)return;
  tbSoftDel('notes',b,function(){
    var D=tbD();
    if(D.notes.some(function(x){return x.id===b.id})||D.bin.some(function(x){return x.id===b.id}))return;
    D.bin.unshift({id:b.id,n:b.n,pg:b.pg,lp:b.lp,ad:b.ad,md:b.md,pin:0,dt:Date.now()});
    D.bin=D.bin.slice(0,100).filter(function(x,i){if(i<100)return true;ntWipe(x.id);return false});
    persist();if(ui.tab==='tb')render('swap');
  });
};
function ntBinHTML(){
  ntBinPurge();
  var B=tbD().bin,h='<button type="button" class="btn bk-add2" data-act="ntBin" data-v="0">'+icon('chev')+__("بازگشت به یادداشت‌ها","Back to notes")+'</button>';
  if(!B.length)return h+'<div class="empty"><div class="badge">'+icon('trash')+'</div><h3>'+__("سطل بازیافت خالی است","The recycle bin is empty")+'</h3><p>'+__("یادداشت پاک‌شده تا ۳۰ روز اینجا می‌ماند و می‌توانی برش گردانی.","A deleted note stays here for 30 days so you can bring it back.")+'</p></div>';
  h+='<h3 class="gh"><span>'+__("سطل بازیافت","Recycle bin")+'</span><span>'+fa(B.length)+'</span></h3>';
  B.forEach(function(b){
    var left=Math.max(1,Math.ceil((b.dt+NT_BIN_DAYS*86400000-Date.now())/86400000));
    h+='<section class="glass rk-card pdf-it"><div class="pdf-row"><div class="pdf-main"><span class="pdf-ic">'+icon('pen')+'</span><span class="pdf-tx"><b>'+esc(b.n)+'</b><small>'+fa(b.pg)+' '+__("صفحه","pages")+' · '+fa(left)+' '+__("روز تا حذف نهایی","days until it is removed")+'</small></span></div>'+
      '<div class="bk-ctl"><button type="button" class="round glass" data-act="ntRestore" data-v="'+b.id+'" aria-label="'+__("بازگردانی","Restore")+'">'+icon('refresh')+'</button><button type="button" class="round glass" data-act="ntKill" data-v="'+b.id+'" aria-label="'+__("حذف همیشگی","Delete forever")+'">'+icon('trash')+'</button></div></div></section>';
  });
  return h+'<button type="button" class="btn bk-add2" data-act="ntBinEmpty" style="color:var(--bad)">'+icon('trash')+__("خالی کردن سطل","Empty the bin")+'</button>';
}
actions.ntBin=function(d){ui.ntbin=d.v==='1';render('swap');window.scrollTo(0,0)};
actions.ntRestore=function(d){
  var D=tbD(),i=D.bin.findIndex(function(x){return x.id===d.v});if(i<0)return;
  if(D.notes.length>=200){toast(__("حداکثر ۲۰۰ یادداشت","200 notes at most"),null,null,'warn');return}
  var b=D.bin.splice(i,1)[0];delete b.dt;D.notes.unshift(b);
  mutate();toast(__("یادداشت برگردانده شد","Note restored"),null,null,'ok',true);
};
actions.ntKill=function(d){
  var D=tbD(),b=D.bin.find(function(x){return x.id===d.v});if(!b)return;
  askConfirm({title:__("حذف همیشگی","Delete forever"),msg:__("این یادداشت برای همیشه پاک می‌شود و برنمی‌گردد.","This note will be deleted for good."),btns:[{t:__("حذف","Delete"),cls:'bad',fn:function(){
    D.bin=D.bin.filter(function(x){return x.id!==b.id});ntWipe(b.id);mutate();
  }}]});
};
actions.ntBinEmpty=function(){
  var D=tbD();if(!D.bin.length)return;
  askConfirm({title:__("خالی کردن سطل","Empty the bin"),msg:__("همهٔ یادداشت‌های سطل برای همیشه پاک می‌شوند.","All notes in the bin will be deleted for good."),btns:[{t:__("خالی کن","Empty"),cls:'bad',fn:function(){
    D.bin.forEach(function(b){ntWipe(b.id)});D.bin=[];mutate();
  }}]});
};
