    function add(a,b,cat,sc,list,nt){a=Math.max(0,a);b=Math.min(n.length-1,b);if(nt){while(b>=nt&&b>a&&SH_STOP.has(n[b]))b--}else{while(b>a&&SH_STOP.has(n[b]))b--;while(a<b&&SH_STOP.has(n[a]))a++}if(b>=a)mine.push({sid:si,a:idx[a],b:idx[b],cat:cat,sc:sc,list:list?1:0})}
