  var budgetW=Math.max(14,Math.round(tot*0.22)),capM=Math.max(4,Math.min(32,Math.round(tot/10))),nL=lines.length;
  var capCat={exam:Math.ceil(capM*0.5),num:Math.ceil(capM*0.35),term:Math.ceil(capM*0.35),head:3,warn:Math.ceil(capM*0.4),key:Math.ceil(capM*0.4),why:Math.ceil(capM*0.45),def:capM};
  var thirdCap=Math.ceil(budgetW*0.5),thirdW=[0,0,0],used={},out=[],perS={},perC={},words=0,lists=0;
  cand.forEach(function(c){c.o=c.a});
  cand.sort(function(a,b){return b.sc-a.sc||a.a-b.a||(b.b-b.a)-(a.b-a.a)});
