      var o=by[it.hx];
      if(!o){o=by[it.hx]={g:it.hx,i:i,c:it.c,ul:it.t==='p',tx:'',y:0};out.push(o);var m=/M[\d.]+ ([\d.]+)/.exec(it.d||'');o.y=m?+m[1]:0}
