function aoSecName(sec){var t=KC_TOP.filter(function(z){return z[0]===sec})[0];return t?t[1]+' '+t[2]:''}
function aoSecGuess(h){
  var x=aoNorm(h);
  if(/انگیزش|انگیزه|روحیه|motiv/.test(x))return 'mot';
  if(/گزارش|report/.test(x))return 'rep';
  if(/برنامه|plan|study/.test(x))return 'plan';
  return null;
}
