async function aoCoachSendReport(sid,x){
  var k=aoPickReportKey(x);
  if(!k){await aoSay(aoT('هنوز گزارشی ثبت نکرده‌ای. بگو «گزارش کار بساز».','You have no saved report yet. Say “make my daily report”.'),true);return}
  var a=kcAnalyze(KC_N),dl='';try{dl=F.long.format(parse(k))}catch(e){}
  aoCoachPush('rep',{r:'u',t:'گزارش‌کار روزانه · '+dl,k:k,ts:Date.now()});
  var ms=kcRepAnalysis(k,a).filter(Boolean);
  ms.forEach(function(m,i){aoCoachPush('rep',{r:'a',t:m,ts:Date.now()+1+i})});persist();
  await aoSay(aoT('گزارش '+dl+' در گروه «'+aoSecName('rep')+'» ارسال شد ✓','Report of '+dl+' sent to “'+aoSecName('rep')+'” ✓'),false,{ok:1,fast:1});
  await aoCoachShowReplies(sid,'rep',ms);
}
async function aoCoachRead(sid,sec){
  var c=(kcD().ch[sec]||[]).slice(-4);
  if(!c.length){await aoSay(aoT('در گروه «'+aoSecName(sec)+'» هنوز پیامی نیست.','No messages yet in “'+aoSecName(sec)+'”.'),true);return}
  await aoSay(aoT('آخرین پیام‌های گروه «'+aoSecName(sec)+'»:','Last messages in “'+aoSecName(sec)+'”:'),true,{fast:1});
  for(var i=0;i<c.length;i++){
    if(sid!==AO.sid)return;
    var m=c[i],txt=m.k?aoT('📝 گزارش‌کار روزانه ارسال شد','📝 Daily report sent'):m.t;
    var eb=m.k?'':emoBigCls(txt),d=document.createElement('div');d.className='ao-m '+(m.r==='u'?'u':'a')+eb;d.innerHTML=(m.r==='u'||eb?'':'<b class="ao-tag">'+aoT('مشاور','Advisor')+'</b>')+'<p>'+(eb?emoBigHTML(txt):esc(txt).replace(/\n/g,'<br>'))+'</p>';
    AO.chat.appendChild(d);aoDown();await aoSleep(240);
  }
  aoCap(aoT('آخرین پیام‌های گروه','Last group messages'));
}
function aoCoachText(raw,hdrOut){
  var m=/(?:بگو|بگید|بگین|بپرس|بپرسید|بنویس|بنویسید|بفرست|بفرستید|پیام بده|پیام بفرست|بذار|بزار|ask|tell|say|write)\s*(?:که\s+)?[:،-]?\s*(.+)$/i.exec(raw);
  var hdr=m?raw.slice(0,m.index):raw,msg=m?m[1].trim():'';
  if(!msg){
    msg=raw.replace(/(?:^|\s)(?:رو|را)?\s*(?:به|از|توی|تو|در|برای|for|to|in)\s+(?:مشاور|گروه)\S*(?:\s+(?:برنامه(?:\s+مطالعاتی)?|گزارش(?:\s*کار)?(?:\s+شبانه)?|انگیزشی))?/g,' ').replace(/(?:^|\s)(?:بگو|بگید|بپرس|بنویس|بفرست|پیام بده|پیام|مشاور)(?=\s|$)/g,' ').replace(/\s+/g,' ').trim();
  }
  hdrOut.h=hdr;return msg;
}
