/* ============ friendly talk: greetings, feelings, small talk and guidance (offline; by voice or text) ============
   Ario understands everyday Persian (and English): hello / how are you / who are you / what can you do,
   feelings (tired, stress, sad, lonely, angry, bored, happy...), jokes, motivation, breathing, study tips,
   "what should I do now?" (built from the real tasks) and "how do I...?" guides.
   Conversation memory (AO_CTX): after "how are you?" or a feeling, the next sentence is understood in that context. */
var AO_CTX=null,AO_LAST={};
/* "shuffle bag": every variant of an answer is used once before any comes back, the first of a new round is never the one just used,
   and the last used index of each answer is kept in localStorage so a restart does not repeat it either */
var AO_BAG={};
function aoLastLoad(){try{var o=JSON.parse(localStorage.getItem('ario.last')||'{}');if(o&&typeof o==='object')Object.keys(o).forEach(function(k){if(AO_LAST[k]==null&&typeof o[k]==='number')AO_LAST[k]=o[k]})}catch(e){}}
function aoLastSave(){try{var o={},ks=Object.keys(AO_LAST).slice(-120);ks.forEach(function(k){o[k]=AO_LAST[k]});localStorage.setItem('ario.last',JSON.stringify(o))}catch(e){}}
function aoPick(a,k){
  if(!a||!a.length)return '';
  if(a.length<2)return a[0];
  if(!k)return a[Math.floor(Math.random()*a.length)];
  if(!aoPick.ld){aoPick.ld=1;aoLastLoad()}
  var bag=AO_BAG[k];
  if(!bag||!bag.length||bag.some(function(i){return i>=a.length})){
    bag=a.map(function(_,i){return i});
    for(var j=bag.length-1;j>0;j--){var r=Math.floor(Math.random()*(j+1)),t=bag[j];bag[j]=bag[r];bag[r]=t}
    /* the next round must not open with the answer that closed the previous one */
    if(bag[bag.length-1]===AO_LAST[k]){var q=bag.length-1,w=Math.floor(Math.random()*q);t=bag[q];bag[q]=bag[w];bag[w]=t}
    AO_BAG[k]=bag;
  }
  var i=bag.pop();AO_LAST[k]=i;aoLastSave();return a[i];
}
function aoName(){var n='';try{n=String(state.profile.name||acctName||'').trim().split(/\s+/)[0]||''}catch(e){}return /[@\d]/.test(n)||n.length>14?'':n}
function aoWc(x){return x?x.split(' ').length:0}
/* a reply object: fa / en text (+ q question), ch = quick buttons [phrase, label fa, label en], ctx = what Ario expects next */
function aoR(k,fa,en,ex){
  var o=ex?Object.assign({},ex):{};
  var f=aoPick(fa,k+'f'),e=aoPick(en,k+'e');
  if(o.q){f+='\n'+o.q[0];e+='\n'+o.q[1]}
  o.fa=f;o.en=e;o.k=k;return o;
}
